 *   keyed/auth-gated job source. The engine forces detect() to null so a keyed
 *   provider only fires on an explicit `provider: <id>` portals.yml entry —
 *   never via auto-detection (no surprise paid/keyed network during a scan).
 * - ingest:  pull postings from a service (email, a Notion board) → Job[]. The
 *   engine appends them to data/pipeline.md canonically.
 * - search:  Job[] for a query string → engine writes canonically to pipeline.
 * - export:  receives a frozen read-only snapshot of the user's tracker and
 *   pushes it to the user's OWN external store; returns {pushed}. No file handle.
 * - notify:  outbound, ephemeral notification of a payload.
 *
 * @typedef {object} PluginHooks
 * @property {{ id: string, detect?: (entry: object) => ({url: string}|null), fetch: (entry: object, ctx: PluginContext) => Promise<object[]> }} [provider]
 * @property {(ctx: PluginContext) => Promise<object[]>} [ingest]
 * @property {(query: string, ctx: PluginContext) => Promise<object[]>} [search]
 * @property {(snapshot: Readonly<object>, ctx: PluginContext) => Promise<{pushed: number}|void>} [export]
 * @property {(payload: Readonly<object>, ctx: PluginContext) => Promise<void>} [notify]
 */

export {};

// Apify transport helper — runs pre-built actors and returns dataset items.
// Used by the Apify provider plugin (plugins/apify/index.mjs).
//
// Ported from the `providers/_apify.mjs` contributed by @ageem23 in #693 (with
// thanks). The only change for the plugin layer: runActor() takes the token as
// an argument (supplied from the plugin's scoped ctx.env) instead of reading
// process.env directly. Files prefixed with _ are never discovered as plugins.
//
// Uses the async pattern (start → poll → fetch dataset) rather than the
// long-polling /run-sync-get-dataset-items endpoint, which holds one HTTP
// connection open for the full actor run and gets cut by some networks /
// Windows SChannel before Apify can flush the response.

// Egress note: this helper keeps its own fetch (its retry / shared-deadline /
// abort logic is the whole point and doesn't map cleanly onto ctx.fetch). It
// self-constrains harder than allowedHosts would — every request is built from
// this single hardcoded base + a strictly-validated actorId (normalizeActorId),
// so it can only ever reach api.apify.com. The manifest's allowedHosts mirrors
// that for doctor/review visibility.
const APIFY_API_BASE = 'https://api.apify.com/v2';
const DEFAULT_RUN_TIMEOUT_MS = 180_000;
const POLL_INTERVAL_MS = 3_000;
const PER_REQUEST_TIMEOUT_MS = 15_000;
const CONNECT_RETRY_ATTEMPTS = 3;
const TERMINAL_STATUSES = new Set(['SUCCEEDED', 'FAILED', 'ABORTED', 'TIMED-OUT']);

export function hasToken(token = process.env.APIFY_TOKEN) {
  return Boolean(token);
}

// Apify accepts both "user/actor" and "user~actor" in URLs; normalize to `~`.
// Validate strictly so a malformed config can't escape the intended
// /acts/<actor>/runs path with extra `/`, `..`, `?`, or `#` characters and
// send our bearer token to an unintended endpoint on api.apify.com.
const ACTOR_ID_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]*[~/][A-Za-z0-9][A-Za-z0-9_.-]*$/;

export function normalizeActorId(actorId) {
  if (typeof actorId !== 'string' || !ACTOR_ID_RE.test(actorId)) {
    throw new Error(
      `apify: invalid actorId ${JSON.stringify(actorId)}. ` +
      `Expected "owner/actor" or "owner~actor" with letters, digits, "_", ".", or "-" only.`
    );
  }
  const [owner, name] = actorId.split(/[~/]/, 2);
  return `${encodeURIComponent(owner)}~${encodeURIComponent(name)}`;
}

// Apify supports auth via ?token= or Authorization: Bearer. The query-string
// form leaks the token into HTTP access logs and any error/log line that
// includes the URL, so always use the header.
function authHeaders(token) {
  return { authorization: `Bearer ${token}` };
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

async function fetchJsonOnce(url, init = {}, timeoutMs = PER_REQUEST_TIMEOUT_MS) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, { ...init, signal: controller.signal });
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      const err = new Error(`HTTP ${res.status}: ${text.slice(0, 300)}`);
      err.status = res.status;
      throw err;
    }
    return await res.json();
  } finally {
    clearTimeout(timer);
  }
}

// Cold connects to api.apify.com occasionally exceed Undici's 10s internal
// connect timeout on this host — retry with backoff before giving up. When
// `deadline` is provided, each attempt's per-request timeout and the
// inter-attempt backoff are both capped against the remaining budget.
async function fetchJson(
  url,
  init = {},
  timeoutMs = PER_REQUEST_TIMEOUT_MS,
  attempts = CONNECT_RETRY_ATTEMPTS,
  deadline = null,
) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    let thisTimeout = timeoutMs;
    if (deadline != null) {
      const remainingMs = deadline - Date.now();
      if (remainingMs <= 0) throw lastErr || new Error('Apify request budget exhausted');
      thisTimeout = Math.min(timeoutMs, remainingMs);
    }
    try {
      return await fetchJsonOnce(url, init, thisTimeout);
    } catch (err) {
      lastErr = err;
      if (err.status >= 400 && err.status < 500) throw err;
      if (i < attempts - 1) {
        const backoff = 500 * (i + 1);
        const sleepMs = deadline != null ? Math.min(backoff, deadline - Date.now()) : backoff;
        if (sleepMs > 0) await sleep(sleepMs);
        else if (deadline != null) throw lastErr;
      }
    }
  }
  throw lastErr;
}

async function startRun(actorId, input, token, deadline = null) {
  const url = `${APIFY_API_BASE}/acts/${normalizeActorId(actorId)}/runs`;
  const body = await fetchJson(
    url,
    {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...authHeaders(token) },
      body: JSON.stringify(input || {}),
    },
    PER_REQUEST_TIMEOUT_MS,
    CONNECT_RETRY_ATTEMPTS,
    deadline,
  );
  const runId = body?.data?.id;
  if (!runId) {
    throw new Error(`Apify did not return a run id: ${JSON.stringify(body).slice(0, 200)}`);
  }
  return runId;
}

// Best-effort — if we give up on a run, stop the actor so credits aren't wasted.
async function abortRun(runId, token) {
  const url = `${APIFY_API_BASE}/actor-runs/${runId}/abort`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5_000);
  try {
    await fetch(url, { method: 'POST', headers: authHeaders(token), signal: controller.signal });
  } catch {} finally {
    clearTimeout(timer);
  }
}

async function waitForRun(runId, token, deadline, timeoutMs) {
  const url = `${APIFY_API_BASE}/actor-runs/${runId}`;
  let lastError;
  while (Date.now() < deadline) {
    const remainingMs = deadline - Date.now();
    if (remainingMs <= 0) break;
    try {
      const body = await fetchJsonOnce(
        url,
        { headers: authHeaders(token) },
        Math.min(PER_REQUEST_TIMEOUT_MS, remainingMs),
      );
      const run = body?.data;
      if (run && TERMINAL_STATUSES.has(run.status)) return run;
      lastError = undefined;
    } catch (err) {
      // 4xx (401/403 auth revoked, 404 run not found) won't succeed on retry.
      if (err?.status >= 400 && err.status < 500) throw err;
      lastError = err;
    }
    const sleepMs = Math.min(POLL_INTERVAL_MS, deadline - Date.now());
    if (sleepMs > 0) await sleep(sleepMs);
  }
  // Fire-and-forget cleanup; don't add abortRun's 5s to our wall-clock budget.
  void abortRun(runId, token).catch(() => {});
  const suffix = lastError ? ` (last error: ${lastError.message})` : '';
  throw new Error(`Apify run ${runId} did not finish within ${Math.round(timeoutMs / 1000)}s${suffix}`);
}

async function fetchDatasetItems(runId, token, deadline = null) {
  const url = `${APIFY_API_BASE}/actor-runs/${runId}/dataset/items`;
  const items = await fetchJson(
    url,
    { headers: authHeaders(token) },
    PER_REQUEST_TIMEOUT_MS * 2,
    CONNECT_RETRY_ATTEMPTS,
    deadline,
  );
  if (!Array.isArray(items)) {
    throw new Error(`Apify run ${runId} returned non-array dataset payload`);
  }
  return items;
}

export async function runActor(actorId, input, { timeoutMs = DEFAULT_RUN_TIMEOUT_MS, token = process.env.APIFY_TOKEN } = {}) {
  if (!token) throw new Error('APIFY_TOKEN not set');
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    throw new Error(`apify: invalid timeoutMs ${JSON.stringify(timeoutMs)} (must be a positive finite number of milliseconds)`);
  }
  // Single deadline shared across startRun → waitForRun → fetchDatasetItems so
  // the caller's timeoutMs is the end-to-end ceiling, not just the wait loop.
  const deadline = Date.now() + timeoutMs;
  const runId = await startRun(actorId, input, token, deadline);
  const run = await waitForRun(runId, token, deadline, timeoutMs);
  if (run.status !== 'SUCCEEDED') {
    const reason = run.statusMessage ? `: ${run.statusMessage}` : '';
    throw new Error(`Apify actor ${actorId} finished with status ${run.status}${reason}`);
  }
  return await fetchDatasetItems(runId, token, deadline);
}

// @ts-check
// ── Reference seed ── This bundled plugin is a stable, reviewed example. To
// extend it, publish career-ops-plugin-<id> with "supersedesBundled": true and
// your version takes precedence once installed (see docs/PLUGINS.md). Bundled
// seeds take only security/compat fixes — feature work happens in the successor repo.
//
// Apify provider plugin — runs any Apify actor and maps its dataset items to
// the {title, url, company, location} Job shape the scanner expects. All
// variation (which actor, what input, how to read fields) lives in portals.yml.
//
// Ported from the generic Apify provider contributed by @ageem23 in #693 (with
// thanks); it also homes the LinkedIn-via-Apify use case from #791/#1202. As a
// KEYED provider it lives here in plugins/ (not the zero-key providers/ dir):
// enable it in config/plugins.yml and put APIFY_TOKEN in .env. It fires ONLY on
// a portals.yml entry that sets `provider: apify` — never via auto-detection.
//
//   tracked_companies:
//     - name: "Indeed — VP Engineering (Chicago)"
//       provider: apify
//       actor: misceres/indeed-scraper
//       input: { position: "VP of Engineering", location: "Chicago, IL", maxItems: 25 }
//       field_map:
//         title:    [positionName, title]    # array = first non-empty wins
//         url:      url
//         company:  [company, companyName]
//         location: [location, formattedLocation]

import { mkdirSync, writeFileSync, existsSync } from 'fs';
import { createHash } from 'crypto';
import { join } from 'path';
import { hasToken, runActor } from './_apify.mjs';

const JDS_DIR = 'jds';
const MIN_JD_BODY_CHARS = 50;

function getPath(obj, p) {
  return p.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
}

// A valid field_map entry is a single key ('positionName') or an ordered list
// of fallback keys (['positionName', 'title']). Reject any other shape at
// config-load time with a clear error instead of crashing mid-scan.
export function isFieldSpec(spec) {
  if (typeof spec === 'string') return true;
  if (Array.isArray(spec) && spec.length > 0 && spec.every(s => typeof s === 'string')) return true;
  return false;
}

function pickField(item, spec) {
  const keys = Array.isArray(spec) ? spec : [spec];
  for (const k of keys) {
    const v = getPath(item, k);
    if (v != null && v !== '') return v;
  }
  return '';
}

const ALLOWED_DEFAULT_KEYS = new Set(['title', 'url', 'company', 'location']);

// Actors return URLs from arbitrary external sites — treat them as untrusted.
// Reject anything that isn't https so javascript:/data:/file:/http: URLs can't
// end up clickable in pipeline.md or in the JD-cache filename hash.
export function isHttpsUrl(value) {
  try {
    return new URL(String(value)).protocol === 'https:';
  } catch {
    return false;
  }
}

function slugify(text) {
  const slug = String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
  if (slug) return slug;
  const hash = createHash('sha1').update(String(text || '')).digest('hex').slice(0, 10);
  return `jd-${hash}`;
}

function yamlEscape(str) {
  const s = String(str ?? '').replace(/\n/g, ' ').trim();
  return `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

// Lightweight HTML → text for actor description fields (enough for downstream
// snippet extraction and full evaluation, not a full parser).
export function htmlToText(s) {
  const raw = String(s || '');
  if (!raw || !/[<&]/.test(raw)) return raw.trim();
  let cleaned = raw
    .replace(/<script\b[\s\S]*?<\/script\b[^>]*>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style\b[^>]*>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<li[^>]*>/gi, '- ')
    .replace(/<\/li>/gi, '\n');
  let prev;
  do {
    prev = cleaned;
    cleaned = cleaned.replace(/<[^>]+>/g, '');
  } while (cleaned !== prev);
  return cleaned
    // Decode &amp; LAST so `&amp;#60;` round-trips to `&#60;` not `<`.
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Write jds/{slug}-{hash}.md and return its relative path. The URL-derived hash
// keeps two distinct postings sharing a company+title from colliding. Atomic
// (flag:'wx') against the 10-worker TOCTOU race; any FS failure returns null so
// the caller falls back to the remote URL.
function saveJd(normalized, descriptionBody, sourceLabel) {
  let relPath = null;
  try {
    mkdirSync(JDS_DIR, { recursive: true });
    const baseSlug = slugify(`${normalized.company}-${normalized.title}`);
    const urlHash = createHash('sha1')
      .update(String(normalized.url || `${normalized.company}-${normalized.title}`))
      .digest('hex')
      .slice(0, 10);
    const filename = `${baseSlug}-${urlHash}.md`;
    const filepath = join(JDS_DIR, filename);
    relPath = `${JDS_DIR}/${filename}`;
    if (existsSync(filepath)) return relPath;
    const today = new Date().toISOString().slice(0, 10);
    const content = `---
title: ${yamlEscape(normalized.title)}
company: ${yamlEscape(normalized.company)}
url: ${yamlEscape(normalized.url)}
location: ${yamlEscape(normalized.location)}
scraped: "${today}"
source: ${sourceLabel}
---

# ${normalized.title} — ${normalized.company}

${descriptionBody}
`;
    writeFileSync(filepath, content, { encoding: 'utf-8', flag: 'wx' });
    return relPath;
  } catch (err) {
    if (err?.code === 'EEXIST' && relPath) return relPath;
    console.warn(`apify: JD cache write failed for ${normalized.title} (${err.code || err.name}: ${err.message}); falling back to remote URL`);
    return null;
  }
}

export function normalizeItem(item, fieldMap, defaults) {
  const out = {
    title: String(pickField(item, fieldMap.title) || ''),
    url: String(pickField(item, fieldMap.url) || ''),
    company: fieldMap.company ? String(pickField(item, fieldMap.company) || '') : '',
    location: fieldMap.location ? String(pickField(item, fieldMap.location) || '') : '',
  };
  for (const [k, v] of Object.entries(defaults || {})) {
    if (!ALLOWED_DEFAULT_KEYS.has(k)) continue;
    if (!out[k]) out[k] = String(v);
  }
  return out;
}

/** The keyed provider hook. Reads APIFY_TOKEN from the plugin's scoped ctx.env. */
export default {
  provider: {
    id: 'apify',
    // Keyed providers never auto-detect (the engine also forces this to null).
    detect() { return null; },

    async fetch(entry, ctx) {
      const token = ctx?.env?.APIFY_TOKEN || process.env.APIFY_TOKEN;
      if (!hasToken(token)) {
        throw new Error('APIFY_TOKEN not set — enable apify in config/plugins.yml and add the token to .env');
      }
      if (!entry.actor) {
        throw new Error(`apify: entry ${entry.name} missing 'actor' (e.g. misceres/indeed-scraper)`);
      }
      if (
        !entry.field_map ||
        !isFieldSpec(entry.field_map.title) ||
        !isFieldSpec(entry.field_map.url) ||
        (entry.field_map.company != null && !isFieldSpec(entry.field_map.company)) ||
        (entry.field_map.location != null && !isFieldSpec(entry.field_map.location)) ||
        (entry.field_map.description != null && !isFieldSpec(entry.field_map.description))
      ) {
        throw new Error(
          `apify: entry ${entry.name} has invalid field_map. Each of title, url, company, ` +
          `location, description must be a string or a non-empty array of strings. title and url are required.`
        );
      }

      const opts = { token };
      if (entry.timeout_ms != null) opts.timeoutMs = entry.timeout_ms;
      const items = await runActor(entry.actor, entry.input || {}, opts);

      const useLocalJd = entry.field_map.description != null;
      const sourceLabel = String(entry.actor || 'apify').replace(/[^a-z0-9]+/gi, '-').toLowerCase();

      return items
        .map(item => {
          const normalized = normalizeItem(item, entry.field_map, entry.defaults);
          if (!normalized.title || !normalized.url) return null;
          if (!isHttpsUrl(normalized.url)) return null;
          if (!useLocalJd) return normalized;
          const descriptionBody = htmlToText(pickField(item, entry.field_map.description));
          if (!descriptionBody || descriptionBody.length < MIN_JD_BODY_CHARS) {
            return normalized;
          }
          const remoteUrl = normalized.url;
          const jdPath = saveJd(normalized, descriptionBody, sourceLabel);
          if (jdPath === null) return normalized;
          normalized.url = `local:${jdPath}`;
          normalized._remote_url = remoteUrl;
          return normalized;
        })
        .filter(j => j && j.title && j.url);
    },
  },
};

// @ts-check
// Pure, side-effect-free Gmail helpers. Ported verbatim from the gmail-helpers
// contributed by @SparshGarg999 in #1203 (with thanks). Files prefixed with _
// are never discovered as plugins.

/**
 * Extract all http/https URLs from a string (plain text or HTML). Normalizes
 * &amp; and strips trailing punctuation. Dedups.
 * @param {string} body
 * @returns {string[]}
 */
export function extractUrls(body) {
  if (!body) return [];
  const urls = [];
  const regex = /https?:\/\/[^\s"'<>\(\)]+/gi;
  let match;
  while ((match = regex.exec(body)) !== null) {
    const url = match[0].replace(/[.,;:!?]+$/, '').replace(/&amp;/g, '&');
    urls.push(url);
  }
  return [...new Set(urls)];
}

/** File types that are page furniture (logos, webfonts, media), never a posting. */
const ASSET_EXT_RE =
  /\.(jpe?g|png|gif|svg|webp|avif|ico|bmp|tiff?|css|js|mjs|woff2?|ttf|otf|eot|mp4|webm|mp3|wav)(\?|#|$)/i;

/** Subdomains that only ever serve static files. */
const ASSET_HOST_PREFIXES = ['cdn.', 'static.', 'assets.', 'img.', 'images.', 'media.'];

/**
 * Is a URL clean and relevant (not a click tracker, unsubscribe link, or pixel)?
 * @param {string} url
 * @returns {boolean}
 */
export function isCleanUrl(url) {
  try {
    const u = new URL(url);
    const lowerUrl = url.toLowerCase();
    const badKeywords = [
      'click', 'track', 'openpixel', 'sendgrid', 'unsubscribe', 'optout',
      'newsletter', 'subscribe', 'w3.org', 'doubleclick', 'googlesyndication',
      'googleadservices', 'mailgun', 'mandrill', 'mjml', 'github.com/login',
      'linkedin.com/legal', 'linkedin.com/help', 'linkedin.com/settings',
    ];
    if (badKeywords.some(kw => lowerUrl.includes(kw))) return false;
    // Page assets, not postings. Job-alert emails embed one company logo per job,
    // and those URLs pass every check above: https, no tracker keyword, hosted on
    // the board's own domain. They land in the pipeline as untitled "job leads" you
    // have to click to discover are 160x160 PNGs. Extension check first (query
    // string included, since CDNs append cache-busters), then the CMS upload paths
    // and asset subdomains that serve files without one.
    const host = u.hostname.toLowerCase();
    if (ASSET_EXT_RE.test(u.pathname + u.search)) return false;
    if (/\/(wp-content|wp-includes)\//i.test(u.pathname)) return false;
    if (host === 'fonts.googleapis.com' || host === 'fonts.gstatic.com') return false;
    if (ASSET_HOST_PREFIXES.some(prefix => host.startsWith(prefix))) return false;
    return u.protocol === 'https:';
  } catch {
    return false;
  }
}

/**
 * DMARC alignment check (anti-spoof gate, fail-closed). Only emails whose
 * Authentication-Results header reports dmarc=pass are trusted.
 * @param {Array<{ name: string, value: string }>} headers
 * @returns {boolean}
 */
export function isAuthenticEmail(headers) {
  if (!Array.isArray(headers)) return false;
  for (const h of headers) {
    if (h.name && h.name.toLowerCase() === 'authentication-results') {
      if (h.value && /dmarc=pass/i.test(h.value)) return true;
    }
  }
  return false;
}

/**
 * Parse "{Role} at {Company}" from a subject line.
 * @param {string} subject
 * @returns {{ role: string, company: string } | null}
 */
export function parseRoleAtCompany(subject) {
  if (!subject) return null;
  let clean = subject.replace(/^(re|fwd|new match|job alert|alert|match|notification|alert for|daily alert for):\s*/i, '').trim();
  clean = clean.split(/\s+[-|]\s+/)[0].trim();
  const match = clean.match(/^(.+?)\s+at\s+(.+)$/i);
  if (match) {
    const role = match[1].trim();
    const company = match[2].trim();
    if (role && company && role.length < 100 && company.length < 100) {
      return { role, company };
    }
  }
  return null;
}

/**
 * Recursively decode a Gmail message payload's base64url body parts to text.
 * @param {any} payload
 * @returns {string}
 */
export function getMessageBody(payload) {
  if (!payload) return '';
  let body = '';
  if (payload.body && payload.body.data) {
    const base64 = payload.body.data.replace(/-/g, '+').replace(/_/g, '/');
    body += Buffer.from(base64, 'base64').toString('utf-8');
  }
  if (payload.parts) {
    for (const part of payload.parts) body += getMessageBody(part);
  }
  return body;
}

/**
 * Best-effort company name from a known ATS URL (greenhouse/lever slug).
 * @param {string} url
 * @returns {string}
 */
export function companyFromUrl(url) {
  try {
    const { hostname, pathname } = new URL(url);
    if (hostname === 'boards.greenhouse.io' || hostname.endsWith('.greenhouse.io') ||
        hostname === 'jobs.lever.co' || hostname.endsWith('.lever.co')) {
      const parts = pathname.split('/').filter(Boolean);
      if (parts.length > 0) return parts[0];
    }
  } catch { /* malformed → no company */ }
  return '';
}

// @ts-check
// ── Reference seed ── This bundled plugin is a stable, reviewed example. To
// extend it, publish career-ops-plugin-<id> with "supersedesBundled": true and
// your version takes precedence once installed (see docs/PLUGINS.md). Bundled
// seeds take only security/compat fixes — feature work happens in the successor repo.
//
// Gmail ingest plugin — pulls job leads from a Gmail label into your pipeline.
//
// Ported from the email-driven ingestion contributed by @SparshGarg999 in #1203
// (with thanks), reshaped to the plugin contract: OAuth credentials come from
// the scoped ctx.env (not credential files), the label/days_back come from
// ctx.settings (config/plugins.yml), and the hook RETURNS Job[] — the engine
// (plugins.mjs), not this plugin, writes them to pipeline.md canonically. No
// `search://` rows are emitted (they aren't real URLs the pipeline can open).
//
// Enable in config/plugins.yml:
//   gmail: { enabled: true, label: "Job Leads", days_back: 7 }
// Add to .env: GMAIL_CLIENT_ID, GMAIL_CLIENT_SECRET, GMAIL_REFRESH_TOKEN.
// Run:  node plugins.mjs run gmail

import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'fs';
import {
  extractUrls, isCleanUrl, isAuthenticEmail, parseRoleAtCompany,
  getMessageBody, companyFromUrl,
} from './_helpers.mjs';

const TOKEN_URL = 'https://oauth2.googleapis.com/token';
const GMAIL_API = 'https://gmail.googleapis.com/gmail/v1/users/me';
const STATE_PATH = 'data/gmail-state.json'; // the plugin's own processed-id cursor

/** Exchange the long-lived refresh token for a short-lived access token. */
async function getAccessToken({ clientId, clientSecret, refreshToken }, fetchFn = globalThis.fetch) {
  const res = await fetchFn(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
      grant_type: 'refresh_token',
    }),
  });
  if (!res.ok) {
    throw new Error(`Gmail token refresh failed: ${res.status} ${(await res.text()).slice(0, 200)}`);
  }
  const data = await res.json();
  if (!data.access_token) throw new Error('Gmail token refresh returned no access_token');
  return data.access_token;
}

function loadProcessedIds() {
  if (!existsSync(STATE_PATH)) return new Set();
  try {
    const state = JSON.parse(readFileSync(STATE_PATH, 'utf-8'));
    return new Set(state.processed_message_ids || []);
  } catch {
    return new Set();
  }
}

function saveProcessedIds(ids) {
  try {
    mkdirSync('data', { recursive: true });
    writeFileSync(STATE_PATH, JSON.stringify({ processed_message_ids: [...ids] }, null, 2), 'utf-8');
  } catch (err) {
    console.warn(`gmail: could not persist processed-id state — ${err.message}`);
  }
}

/** @type {{ ingest: (ctx: any) => Promise<object[]> }} */
export default {
  async ingest(ctx) {
    const clientId = ctx?.env?.GMAIL_CLIENT_ID;
    const clientSecret = ctx?.env?.GMAIL_CLIENT_SECRET;
    const refreshToken = ctx?.env?.GMAIL_REFRESH_TOKEN;
    if (!clientId || !clientSecret || !refreshToken) {
      throw new Error('gmail: missing GMAIL_CLIENT_ID / GMAIL_CLIENT_SECRET / GMAIL_REFRESH_TOKEN in .env');
    }

    const label = ctx?.settings?.label || 'Job Leads';
    const daysBack = Number(ctx?.settings?.days_back ?? 7);
    if (!Number.isInteger(daysBack) || daysBack <= 0) {
      throw new Error(`gmail: invalid days_back "${ctx?.settings?.days_back}" (must be a positive integer)`);
    }

    const token = await getAccessToken({ clientId, clientSecret, refreshToken }, ctx.fetch);
    const auth = { Authorization: `Bearer ${token}` };
    const query = `label:"${label}" newer_than:${daysBack}d`;
    ctx.log(`gmail: querying ${query}`);

    // List message ids (paginated). ctx.fetch throws on a non-2xx (with the body
    // in the message), so a failed page surfaces a clear error.
    const messages = [];
    let pageToken = null;
    do {
      let url = `${GMAIL_API}/messages?q=${encodeURIComponent(query)}`;
      if (pageToken) url += `&pageToken=${pageToken}`;
      const data = await (await ctx.fetch(url, { headers: auth })).json();
      if (data.messages) messages.push(...data.messages);
      pageToken = data.nextPageToken;
    } while (pageToken);

    const processedIds = loadProcessedIds();
    const seenUrls = new Set();
    const jobs = [];

    for (const m of messages) {
      if (processedIds.has(m.id)) continue;
      // Per-message resilience: a single bad detail fetch is skipped, not fatal.
      let msg;
      try {
        msg = await (await ctx.fetch(`${GMAIL_API}/messages/${m.id}?format=full`, { headers: auth })).json();
      } catch (err) {
        console.warn(`gmail: failed to fetch message ${m.id} — ${err.message}`);
        continue;
      }
      const headers = msg.payload?.headers || [];
      const subject = headers.find(h => h.name?.toLowerCase() === 'subject')?.value || '';

      // Fail-closed on spoofed mail (DMARC).
      if (!isAuthenticEmail(headers)) {
        console.warn(`gmail: skipping spoofed/unauthenticated email "${subject}"`);
        processedIds.add(m.id);
        continue;
      }

      const seed = parseRoleAtCompany(subject);
      const cleanUrls = extractUrls(getMessageBody(msg.payload)).filter(isCleanUrl);
      for (const url of cleanUrls) {
        if (seenUrls.has(url)) continue;
        seenUrls.add(url);
        jobs.push({
          title: seed?.role || 'Job lead (email)',
          url,
          company: companyFromUrl(url) || seed?.company || '',
          location: '',
        });
      }
      processedIds.add(m.id);
    }

    if (!ctx?.dryRun) saveProcessedIds(processedIds);
    return jobs;
  },
};

#!/usr/bin/env node
// CLI entrypoint for the H-1B sponsor check.
// Usage: node plugins/h1b-sponsor/check.mjs <company-name> [--json|--summary] [--refresh] [--search] [--cache-dir <path>]
//   --search lists every matching employer entity instead of checking one.
// Env: H1B_INDEX_PATH (optional; relocates the local index).
//      H1B_API_BASE   (optional; opts into the HTTP backend, see below).
//      H1B_API_TOKEN  (optional; HTTP backend only, raises the rate limit).
//
// Backends, in order:
//   1. An HTTP endpoint, used when H1B_API_BASE names one explicitly.
//   2. The local index (data/h1b/), installed by install-h1b-index.mjs. The
//      default, and the only one where the question never leaves the machine.
// With neither, the CLI reports `unknown` and says how to install the index.
// It does NOT fall back to a default host: which employers someone checks
// discloses that they need a visa and who they are applying to, so that
// destination is a choice the user makes, never one made for them by a missing
// file.
//
// Output format (JSON):
//   { found, employerId, displayName, hasSponsorshipHistory,
//     totals: { n_lca, n_certified, n_pwd, n_perm, first_year, last_year, does_gc },
//     redFlags: { staffing_shop: {...} | null },
//     friendlinessTier, source, fetchedAt }
// n_lca counts what the employer FILED. n_certified is how much of it came
// back certified, reported beside it and never in place of it: a denial is
// USCIS's decision and a withdrawal is usually the candidate taking another
// offer, so neither is evidence the employer will not sponsor. It is null when
// the backend does not report it, which is not the same as 0.

import * as httpBackend from './lib/api.mjs';
import { num } from './lib/api.mjs';
import * as localBackend from './lib/index.mjs';
import { readCache, writeCache } from './lib/cache.mjs';
import { classifyTier } from './lib/tier.mjs';

// Set once main() has chosen a backend. Null while unchosen and after a failed
// choice, which is what lets the error handler report a source of null instead
// of naming an endpoint the user never selected.
let backend = null;

/**
 * Pick where this lookup is answered from.
 *
 * Explicit choice first, then the local default, then an error. H1B_API_BASE is
 * something a user only ever sets on purpose, and an installed index used to
 * win over it unconditionally, so that choice was read and then ignored without
 * a word. Silently disregarding what someone configured is the same surprise as
 * silently picking a host for them, which is what the rest of this ordering
 * exists to rule out; both are now impossible.
 *
 * With nothing set, the index answers, so the default path still has no server
 * in it. Selection is deliberately not a fallback chain in the other direction:
 * a missing index does not silently become a request to somebody's server. It
 * becomes an error that says how to install the index.
 */
async function selectBackend() {
  if (process.env.H1B_API_BASE !== undefined) {
    const token = process.env.H1B_API_TOKEN;
    return {
      kind: 'api',
      source: httpBackend.apiBase(),
      opts: token ? { token } : {},
      resolveEmployer: httpBackend.resolveEmployer,
      searchEmployers: httpBackend.searchEmployers,
      getEmployerProfile: httpBackend.getEmployerProfile,
    };
  }
  if (localBackend.hasIndex()) {
    return {
      kind: 'index',
      // The index digest, so a cached answer is tied to the exact data that
      // produced it and a refreshed index invalidates the old numbers.
      source: await localBackend.indexSource(),
      opts: {},
      resolveEmployer: localBackend.resolveEmployer,
      searchEmployers: localBackend.searchEmployers,
      getEmployerProfile: localBackend.getEmployerProfile,
    };
  }
  throw new Error(
    'no local H-1B index and no H1B_API_BASE. Install the index with: node plugins/h1b-sponsor/install-h1b-index.mjs '
    + '(about 8 MiB of public DOL data; lookups then stay on this machine). To use an HTTP endpoint instead, '
    + 'set H1B_API_BASE to one you trust.',
  );
}

// Where the answer came from, reported back to the caller. The HTTP path names
// the employer's own URL so the number can be checked by hand; the local path
// names the index build, which is the equivalent handle for data on disk.
function sourceRef(employerId) {
  if (!backend) return null;
  if (backend.kind === 'index') return backend.source;
  return employerId
    ? `${backend.source}/employers/${encodeURIComponent(employerId)}`
    : `${backend.source}/employers`;
}

// Text from the backend goes through this before any non-JSON output, whether
// it came from an endpoint or off the index: collapse whitespace so a line
// stays a line, then strip C0, DEL, and C1 control characters so a crafted
// name cannot smuggle terminal escapes or forged rows into the text output.
// JSON output keeps the raw fields. The collapse
// runs first because newlines and tabs are control chars too, and stripping
// them before the collapse would glue words together instead of separating
// them; what survives the collapse (ESC, BEL, DEL, C1) is not whitespace.
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS = /[\u0000-\u001f\u007f-\u009f]/g;
function displayClean(s) {
  return String(s || '').replace(/\s+/g, ' ').replace(CONTROL_CHARS, '').trim();
}

// What the numbers in a cache entry MEAN, versioned. An entry written before
// this bump carries a certified count in `n_lca`, because that is what the
// field held then; the tier now reads that field as filings, so serving one
// would answer with a number that means something else, and quietly. Entries
// without the marker are misses (see main()), which costs one re-read.
//
// The local backend self-heals without this: its source stamp is the index
// digest, so a rebuilt index invalidates its own entries. The HTTP path has no
// such handle, since an endpoint's URL does not change when its payload's
// meaning does, and that is the gap the marker closes.
const CACHE_SCHEMA = 2;

// The cache is an optimization: a failed write (read-only FS, full disk, a
// --cache-dir typo) must never discard a lookup that already succeeded and
// already spent rate-limit budget.
async function writeCacheSafe(name, data, opts) {
  try {
    await writeCache(name, { ...data, schema: CACHE_SCHEMA }, opts);
  } catch (err) {
    const msg = displayClean((err && err.message) ? err.message : err);
    process.stderr.write(`h1b-sponsor: cache write failed (${msg}); continuing without cache\n`);
  }
}

function parseArgs(argv) {
  const args = { name: null, format: 'summary', refresh: false, cacheDir: null, search: false };
  const rest = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json') args.format = 'json';
    else if (a === '--summary') args.format = 'summary';
    else if (a === '--refresh') args.refresh = true;
    else if (a === '--search') args.search = true;
    else if (a === '--cache-dir') {
      // Consumes the following argument so it is never read as the company name.
      const next = argv[i + 1];
      if (typeof next === 'string' && next.trim()) args.cacheDir = next;
      i++;
    } else if (a.startsWith('-')) {
      // unknown flag - ignore silently for forward compatibility
    } else rest.push(a);
  }
  args.name = rest.join(' ').trim();
  return args;
}


function formatSummary(result) {
  const clean = displayClean;
  if (!result.found) return `unknown: ${clean(result.displayName) || 'unknown company'}`;
  const t = result.totals || {};
  const range = (t.first_year && t.last_year)
    ? `${t.first_year}-${t.last_year}`
    : (t.last_year || t.first_year || 'n/a');
  return `${result.friendlinessTier}: ${clean(result.displayName)} - ${t.n_lca ?? 0} LCAs, ${t.n_pwd ?? 0} PWDs, ${t.n_perm ?? 0} PERMs, active ${range}`;
}

function buildResult(displayName, employerId, profile, source, fetchedAt) {
  const tier = classifyTier(profile);
  const staffing = (profile && profile.red_flags && profile.red_flags.staffing_shop) || null;
  const nLca = Number(profile?.n_lca ?? 0) || 0;
  const nPwd = Number(profile?.n_pwd ?? 0) || 0;
  const nPerm = Number(profile?.n_perm ?? 0) || 0;
  return {
    found: true,
    employerId,
    displayName,
    hasSponsorshipHistory: (nLca + nPwd + nPerm) > 0,
    totals: {
      n_lca: nLca,
      // Not coerced through `|| 0` like the counts above: 0 certified is a
      // real answer about an employer that filed, and null means the backend
      // did not report the number at all.
      n_certified: num(profile?.n_certified),
      n_pwd: nPwd,
      n_perm: nPerm,
      first_year: profile?.first_year ?? null,
      last_year: profile?.last_year ?? null,
      does_gc: profile?.does_gc === true,
    },
    redFlags: { staffing_shop: staffing },
    friendlinessTier: tier,
    source,
    fetchedAt,
  };
}

function notFoundResult(name, fetchedAt = new Date().toISOString()) {
  return {
    found: false,
    employerId: null,
    displayName: name,
    hasSponsorshipHistory: false,
    totals: { n_lca: 0, n_certified: null, n_pwd: 0, n_perm: 0, first_year: null, last_year: null, does_gc: false },
    redFlags: { staffing_shop: null },
    friendlinessTier: 'unknown',
    source: sourceRef(null),
    fetchedAt,
  };
}

function emit(format, obj) {
  if (format === 'json') {
    process.stdout.write(JSON.stringify(obj, null, 2) + '\n');
  } else {
    process.stdout.write(formatSummary(obj) + '\n');
  }
}

// --search lists every matching entity instead of resolving to one, because a
// company files under many distinct FEINs (Amazon has dozens) and the caller
// may need to pick the exact one. Each listed name is checkable on its own: an
// exact name resolves straight to that entity.
function emitSearch(format, query, total, results) {
  const clean = displayClean;
  if (format === 'json') {
    process.stdout.write(JSON.stringify({ query, total, shown: results.length, results }, null, 2) + '\n');
    return;
  }
  if (results.length === 0) {
    process.stdout.write(`no matches for "${clean(query)}"\n`);
    return;
  }
  const header = total > results.length
    ? `${results.length} of ${total} matches for "${clean(query)}" (narrow the query to see the rest):`
    : `${results.length} match${results.length === 1 ? '' : 'es'} for "${clean(query)}":`;
  const rows = results.map(r => `  ${clean(r.id)}  ${clean(r.name)}`);
  process.stdout.write([header, ...rows].join('\n') + '\n');
}

async function main() {
  const { name, format, refresh, cacheDir, search } = parseArgs(process.argv.slice(2));
  if (!name) {
    process.stderr.write('Usage: node plugins/h1b-sponsor/check.mjs <company-name> [--json|--summary] [--refresh] [--search] [--cache-dir <path>]\n');
    process.exit(2);
  }

  // Chosen before anything else runs: with no backend available this throws,
  // and it throws before a single request or read is issued.
  backend = await selectBackend();
  const opts = backend.opts;
  const cacheOpts = cacheDir ? { cacheDir } : {};

  // --search lists every matching entity and stops; it never resolves to one or
  // touches the cache. Each listed name can then be checked on its own.
  if (search) {
    const { total, results } = await backend.searchEmployers(name, opts);
    emitSearch(format, name, total, results);
    return;
  }

  if (!refresh) {
    const cached = await readCache(name, cacheOpts);
    if (cached) {
      // One rule for both kinds of entry. A negative entry carries no counts,
      // so the schema bump is not strictly load-bearing for it; versioning it
      // with the rest is what keeps "is this entry from this code" a single
      // question rather than two that can drift apart.
      const sameSchema = Boolean(cached.data) && cached.data.schema === CACHE_SCHEMA;
      if (sameSchema && cached.negative && cached.data.source === backend.source) {
        const out = notFoundResult(name);
        // Keep source in its documented form; the stale fetchedAt is what
        // signals this answer came from cache.
        out.fetchedAt = cached.fetchedAt;
        emit(format, out);
        return;
      }
      const { displayName, employerId, profile, source } = cached.data || {};
      // An answer from one backend is not an answer from another, and the
      // source field is rebuilt from the CURRENT one, so serving a stale entry
      // across a switch would label one backend's data as the other's. This
      // covers both endpoints (a different H1B_API_BASE) and index builds (a
      // quarterly refresh changes the digest), and it treats entries written
      // before this field existed as misses rather than trusting them blind.
      if (sameSchema && displayName && employerId && profile && source === backend.source) {
        const out = buildResult(displayName, employerId, profile, sourceRef(employerId), cached.fetchedAt);
        emit(format, out);
        return;
      }
    }
  }

  const match = await backend.resolveEmployer(name, opts);
  if (!match) {
    const out = notFoundResult(name);
    await writeCacheSafe(name, { name, source: backend.source }, { ...cacheOpts, negative: true, fetchedAt: out.fetchedAt });
    emit(format, out);
    return;
  }

  const profile = await backend.getEmployerProfile(match.id, opts);
  const now = new Date().toISOString();
  // A null profile is unreadable on the way back out (the cache-hit guard
  // requires a truthy profile), so writing it would only burn a file slot.
  if (profile) {
    await writeCacheSafe(name, {
      displayName: match.displayName,
      employerId: match.id,
      profile,
      source: backend.source,
    }, { ...cacheOpts, fetchedAt: now });
  }
  const out = buildResult(match.displayName, match.id, profile, sourceRef(match.id), now);
  emit(format, out);
}

main().catch(err => {
  // The message can embed up to 200 chars of API-controlled response body, and
  // the summary contract is one line: collapse all whitespace before printing.
  const message = displayClean((err && err.message) ? err.message : err);
  const argv = process.argv.slice(2);
  const format = argv.includes('--json') ? 'json' : 'summary';
  // Emit the full documented envelope even on error so consumers reading
  // totals/redFlags without checking `error` first don't crash.
  const { name, search } = parseArgs(argv);
  // A --search run has its own output shape; keep it on error for the same
  // reason, so a consumer reading results/shown does not get the check envelope.
  if (search) {
    if (format === 'json') {
      process.stdout.write(JSON.stringify({ query: name || '', total: 0, shown: 0, results: [], error: message }, null, 2) + '\n');
    } else {
      process.stdout.write(`search failed: ${message}\n`);
    }
    // process.exit() does not wait for a pending stdout write to flush, so on
    // a piped stdout (the --json consumer case) it can truncate the envelope
    // right when a caller most needs it. Setting exitCode and returning lets
    // the process exit once the event loop drains, after the write completes.
    process.exitCode = 1;
    return;
  }
  const payload = { ...notFoundResult(name || 'unknown company'), error: message };
  if (format === 'json') {
    process.stdout.write(JSON.stringify(payload, null, 2) + '\n');
  } else {
    process.stdout.write(`unknown: ${message}\n`);
  }
  process.exitCode = 1;
  return;
});

// H-1B Sponsor Check plugin entry point.
// This plugin does not source jobs; the real API surface is the CLI
// (check.mjs) plus the companion skill. The ingest hook is declared only so
// the manifest satisfies the engine's non-empty hooks[] requirement.
export default {
  async ingest(_ctx) {
    return [];
  }
};

#!/usr/bin/env node
// Downloads the local H-1B index so check.mjs can answer offline.
// Usage: node plugins/h1b-sponsor/install-h1b-index.mjs [--tag <release>] [--force]
//
// This is the one command in the plugin that reaches the network on the read
// path's behalf, and it is deliberately separate from check.mjs: keeping the
// download out of the checking CLI is what makes "a local check sends nothing"
// a property of the file rather than a promise about a code path. It is also
// an outward action in the same sense token.mjs is, so an agent runs it only
// when the user has asked for it.
//
// The release publishes two assets: the quarter's index, named for the quarter
// it was built from (index-2026Q2.ndjson.gz), and index-latest.json, a pointer
// object naming that file and its sha256. The pointer is read first, then the
// file it names, and the digest is verified against the bytes on disk BEFORE
// they are moved into place, so a truncated or substituted download is never
// what a lookup reads.
//
// Both live under a permanent `index-latest` tag whose assets are replaced each
// quarter, and the URLs here are built from that tag rather than from GitHub's
// /releases/latest/download/ path. That path resolves to the newest release of
// ANY kind in the repo, so the day that repo cuts a release for its own code,
// every client following it would start downloading the wrong thing. A fixed
// tag cannot drift that way.

import { mkdir, rename, unlink, writeFile } from 'node:fs/promises';
import { createWriteStream, existsSync } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { once } from 'node:events';
import path from 'node:path';
import { isMainModule } from '../../lib/is-main-module.mjs';
import { fetchWithTimeout, readBoundedText } from './lib/api.mjs';
import { indexPath, metaPath } from './lib/index.mjs';

const REPO = 'msampath/h1b-sponsor-data';
// The tag whose assets the publisher replaces each quarter. Overridable with
// --tag for a self-hosted fork or a pinned per-quarter tag; the pointer and the
// file it names always come from the same tag.
const DEFAULT_TAG = 'index-latest';
const POINTER = 'index-latest.json';
const USER_AGENT = 'career-ops-plugin-h1b-sponsor/1.0';
const USAGE = 'Usage: node plugins/h1b-sponsor/install-h1b-index.mjs [--tag <release>] [--force]';

// A release download starts on github.com and is answered by whichever asset
// host GitHub redirects to, so the egress guard is given all of them rather
// than the single API host it uses on the read path. Everything outside this
// list is still refused mid-redirect, before the request is issued to it.
const RELEASE_ORIGINS = [
  'https://github.com',
  'https://objects.githubusercontent.com',
  'https://release-assets.githubusercontent.com',
];
const MAX_REDIRECTS = 5;

// The index is ~8 MiB and grows a little each quarter. The ceiling is generous
// enough not to break on that and small enough that a runaway or hostile body
// cannot fill the user's disk before the digest gets a chance to reject it.
const MAX_INDEX_BYTES = 64 * 1024 * 1024;
const MAX_POINTER_BYTES = 4 * 1024;
const POINTER_TIMEOUT_MS = 30_000;
// 8 MiB over a slow link takes longer than any API call, and the abort timer
// covers the whole streamed body rather than just the headers.
const ASSET_TIMEOUT_MS = 300_000;

const SHA256_RE = /^[0-9a-f]{64}$/;
// The pointer names the file to fetch, so that name arrives over the network
// and is then used to build a URL. Restricting it to one path component of
// ordinary filename characters is what keeps it from walking out of the release
// (a `..` or a slash) or from becoming a path of its own. Deliberately not
// pinned to a specific extension: the publisher may change how it compresses
// without this needing a release of its own.
const FILENAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function assetUrl(tag, name) {
  return `https://github.com/${REPO}/releases/download/${encodeURIComponent(tag)}/${encodeURIComponent(name)}`;
}

function guardedFetch(url, opts, consume) {
  return fetchWithTimeout(url, {
    headers: { 'Accept': '*/*', 'User-Agent': USER_AGENT },
    allowedOrigins: RELEASE_ORIGINS,
    maxRedirects: MAX_REDIRECTS,
    ...opts,
  }, consume);
}

/**
 * Read the pointer the release publishes at index-latest.json:
 * `{ version, built_at, employers, bytes, sha256, filename }`. Only `filename`
 * and `sha256` decide what happens next; `version` is carried through to the
 * sidecar so the installed quarter can be reported later without downloading
 * anything again.
 *
 * Bounded with readBoundedText, like every other body this plugin reads: the
 * pointer is a few hundred bytes and nothing served under that name should ever
 * be large enough to be worth buffering. The index itself is the exception and
 * streams to disk instead.
 *
 * Both fields are validated before use. They come from the network, and one of
 * them is about to become part of a URL and the other the sole thing standing
 * between a substituted download and a lookup that trusts it.
 */
async function fetchPointer(fetchImpl, url) {
  const out = await fetchImpl(url, { timeoutMs: POINTER_TIMEOUT_MS }, async res => {
    if (res.status !== 200) return { status: res.status };
    const read = await readBoundedText(res, MAX_POINTER_BYTES);
    return read.oversized ? { oversized: true } : { text: read.text };
  });
  if (out.status) throw new Error(`could not read the release pointer (HTTP ${out.status}): ${url}`);
  if (out.oversized) throw new Error(`the release pointer is implausibly large: ${url}`);

  let doc;
  try {
    doc = JSON.parse(String(out.text || ''));
  } catch {
    throw new Error(`the release pointer is not JSON: ${url}`);
  }
  if (!doc || typeof doc !== 'object') throw new Error(`the release pointer is not an object: ${url}`);

  const filename = String(doc.filename || '');
  if (!FILENAME_RE.test(filename)) {
    throw new Error(`the release pointer names an unusable index filename (${JSON.stringify(doc.filename)}): ${url}`);
  }
  const sha256 = String(doc.sha256 || '').trim().toLowerCase();
  if (!SHA256_RE.test(sha256)) {
    throw new Error(`the release pointer does not carry a sha256 digest: ${url}`);
  }
  // Recorded, never acted on, so a missing or odd value costs a label rather
  // than the install. Bounded because it lands in a file on disk.
  const version = doc.version === undefined || doc.version === null
    ? null
    : String(doc.version).slice(0, 64);
  return { filename, sha256, version };
}

/**
 * Stream the asset to `tmpFile`, hashing as it goes, and return the digest.
 *
 * Streamed rather than buffered: the body is millions of times the size of
 * anything else this plugin reads, and readBoundedText's 1 MiB ceiling exists
 * precisely because nothing on the API path should ever be this big. Hashing
 * during the write means the file is never read a second time to verify it.
 */
async function downloadAsset(fetchImpl, url, tmpFile) {
  return fetchImpl(url, { timeoutMs: ASSET_TIMEOUT_MS }, async res => {
    if (res.status !== 200) throw new Error(`could not download the index (HTTP ${res.status}): ${url}`);
    const declared = Number(res.headers?.get?.('content-length'));
    if (Number.isFinite(declared) && declared > MAX_INDEX_BYTES) {
      throw new Error(`the published index exceeds ${MAX_INDEX_BYTES} bytes (${declared}): ${url}`);
    }
    if (!res.body || typeof res.body.getReader !== 'function') {
      throw new Error(`the index response carried no readable body: ${url}`);
    }

    const hash = createHash('sha256');
    const out = createWriteStream(tmpFile);
    // A write failure (disk full, an unwritable target) arrives as an 'error'
    // event on the stream, and an EventEmitter error with no listener is an
    // uncaughtException: the CLI died on a stack trace instead of returning
    // the envelope, and the cleanup that removes the partial .tmp file never
    // ran. Recording the error here makes the crash impossible; the checks
    // below turn it into the ordinary failure it is. once(out, 'drain') needs
    // no extra wiring, it already rejects when 'error' fires mid-wait.
    let writeError = null;
    out.on('error', err => { writeError = err; });
    const reader = res.body.getReader();
    let total = 0;
    try {
      for (;;) {
        if (writeError) {
          await reader.cancel().catch(() => {});
          throw writeError;
        }
        const { done, value } = await reader.read();
        if (done) break;
        if (!value) continue;
        total += value.byteLength;
        if (total > MAX_INDEX_BYTES) {
          await reader.cancel().catch(() => {});
          throw new Error(`the published index exceeds ${MAX_INDEX_BYTES} bytes: ${url}`);
        }
        hash.update(value);
        // Respect backpressure: an 8 MiB body written without it queues the
        // whole file in memory, which is the thing streaming was for.
        if (!out.write(value)) await once(out, 'drain');
      }
    } finally {
      await new Promise(resolve => out.end(resolve));
    }
    // end() above flushes the tail, so a failure during that flush, or one
    // that raced the final read, is only visible here. The digest must not
    // vouch for bytes that never landed on disk.
    if (writeError) throw writeError;
    return { digest: hash.digest('hex'), bytes: total };
  });
}

/**
 * Install the index. Returns a plain result so every branch is testable without
 * a live download: `{ ok: true, ... }` or `{ ok: false, exitCode, message }`.
 * `fetchImpl` is injectable and must have fetchWithTimeout's shape.
 */
export async function installIndex({ fetchImpl = guardedFetch, tag = null, force = false, targetPath } = {}) {
  let target;
  try {
    target = targetPath || indexPath();
  } catch (err) {
    return { ok: false, exitCode: 1, message: (err && err.message) ? err.message : String(err) };
  }

  if (existsSync(target) && !force) {
    return {
      ok: false,
      exitCode: 0,
      message: `an index is already installed at ${target}. Pass --force to replace it with the current release.`,
    };
  }

  const release = tag || DEFAULT_TAG;
  const tmpFile = `${target}.${randomUUID()}.tmp`;
  let pointer;
  try {
    pointer = await fetchPointer(fetchImpl, assetUrl(release, POINTER));
  } catch (err) {
    return { ok: false, exitCode: 1, message: (err && err.message) ? err.message : String(err) };
  }
  const expected = pointer.sha256;
  const url = assetUrl(release, pointer.filename);

  try {
    await mkdir(path.dirname(target), { recursive: true });
    const { digest, bytes } = await downloadAsset(fetchImpl, url, tmpFile);
    if (digest !== expected) {
      // Nothing has been moved into place yet, so refusing here means the
      // previously installed index (if any) keeps serving and no lookup ever
      // reads bytes that failed their own checksum.
      await unlink(tmpFile).catch(() => {});
      return {
        ok: false,
        exitCode: 1,
        message: `checksum mismatch: the download hashed to ${digest} but the release publishes ${expected}. Nothing was installed.`,
      };
    }
    await rename(tmpFile, target);
    // version is the quarter the release was built from. Recording it here is
    // what lets the installed build be named later without asking GitHub again.
    await writeFile(metaPath(target), `${JSON.stringify({
      sha256: digest,
      bytes,
      version: pointer.version,
      filename: pointer.filename,
      url,
      installedAt: new Date().toISOString(),
    }, null, 2)}\n`, 'utf8');
    return { ok: true, target, bytes, digest, url, version: pointer.version, filename: pointer.filename };
  } catch (err) {
    await unlink(tmpFile).catch(() => {});
    const reason = (err && err.name === 'AbortError')
      ? `no response within ${ASSET_TIMEOUT_MS / 1000}s`
      : ((err && err.message) ? err.message : String(err));
    return { ok: false, exitCode: 1, message: `could not install the index (${reason})` };
  }
}

function parseArgs(argv) {
  const args = { tag: null, force: false, ok: true };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--force') args.force = true;
    else if (a === '--tag') {
      const next = argv[i + 1];
      if (typeof next !== 'string' || !next.trim() || next.startsWith('-')) { args.ok = false; break; }
      args.tag = next.trim();
      i++;
    } else args.ok = false;
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.ok) {
    process.stderr.write(`${USAGE}\n`);
    process.exitCode = 2;
    return;
  }

  const result = await installIndex({ tag: args.tag, force: args.force });
  if (!result.ok) {
    // Errors go to stderr with an exit code rather than process.exit, so the
    // stream is flushed before the process ends.
    process.stderr.write(`${result.message}\n`);
    process.exitCode = result.exitCode;
    return;
  }
  process.stdout.write([
    `installed ${(result.bytes / 1048576).toFixed(1)} MiB to ${result.target}`,
    `build ${result.version || result.filename}`,
    `sha256 ${result.digest}`,
    '',
    'Lookups now run locally and send nothing. Refresh when DOL publishes a new',
    'quarter by re-running this command with --force.',
  ].join('\n') + '\n');
}

// Run the CLI only when invoked as a script: installIndex is imported by the
// test suite, and an unguarded main() would run on import with the importer's
// argv and set the importer's exit code.
if (isMainModule(import.meta.url)) {
  main().catch(err => {
    process.stderr.write(`could not install the index (${(err && err.message) ? err.message : err})\n`);
    process.exitCode = 1;
  });
}

// Thin client for the H-1B sponsorship API.
// Uses global fetch + AbortController. Handles the 429/Retry-After retry-once
// policy specified in the plugin contract. Self-contained: no imports from
// career-ops core (so this plugin can later ship as its own npm package).

const DEFAULT_BASE = 'https://api.surakshith.com/immigration/v1';

/**
 * Where the plugin sends lookups. Defaults to the maintained instance and is
 * overridable with H1B_API_BASE, so a bundled plugin is never a hard
 * dependency on one host: the dataset is public DOL disclosure data and the
 * worker that serves it is open source, so anyone can run their own. Which
 * companies a person checks says both that they need a visa and who they are
 * applying to, and that is theirs to route.
 *
 * Resolved on first use rather than at import. An invalid value must fail the
 * command that needed it, not the act of loading the module: this file is
 * imported by the repo's own test runner, and a throw at import time took the
 * whole suite down with a stack trace instead of one red test.
 *
 * Everything downstream follows this, including the redirect guard in
 * fetchWithTimeout, so pointing at a private instance narrows egress rather
 * than widening it.
 */
let resolvedBase;

export function apiBase() {
  // Only a successful resolve is memoized; a bad value keeps throwing so the
  // failure cannot be masked by an earlier call that happened to succeed.
  if (resolvedBase === undefined) resolvedBase = resolveBase();
  return resolvedBase;
}

function resolveBase() {
  const raw = process.env.H1B_API_BASE;
  // Absent means "use the default". Present but blank is a misconfiguration
  // (an unset shell variable, an empty .env line, a CI secret that did not
  // populate), and silently falling back would send someone's shortlist and
  // their token to a host they believed they had replaced.
  if (raw === undefined) return DEFAULT_BASE;
  const trimmed = String(raw).trim();
  if (!trimmed) {
    throw new Error('H1B_API_BASE is set but empty. Unset it to use the default endpoint.');
  }

  let parsed;
  try {
    parsed = new URL(trimmed);
  } catch {
    throw new Error(`H1B_API_BASE is not a valid URL: ${trimmed}`);
  }
  if (parsed.username || parsed.password) {
    // Undici refuses a credentialed Request anyway, and the value reaches
    // stdout through the source field, so this would print a password.
    throw new Error('H1B_API_BASE must not embed credentials.');
  }
  if (parsed.search || parsed.hash) {
    // Paths are appended, so a query or fragment swallows them: the request
    // would go to the base itself and answer about a company never asked for.
    throw new Error('H1B_API_BASE must not contain a query string or a fragment.');
  }
  // Plain http would put an Authorization header on the wire in the clear.
  // Loopback is exempt so a self-hoster can develop against a local worker,
  // but only for http. Exempting every scheme on a loopback host let
  // ftp://localhost and ws://localhost past validation, and those die later
  // inside fetch as a bare "fetch failed", which is the opaque failure this
  // check exists to replace with a named configuration error.
  const loopback = /^(localhost|127\.\d+\.\d+\.\d+|\[::1\]|::1)$/i.test(parsed.hostname);
  const allowedScheme = parsed.protocol === 'https:' || (parsed.protocol === 'http:' && loopback);
  if (!allowedScheme) {
    throw new Error(`H1B_API_BASE must use https, or http on loopback: ${trimmed}`);
  }
  // Appended as `${base}/employers/...`, so a trailing slash would double up.
  return trimmed.replace(/\/+$/, '');
}
const USER_AGENT = 'career-ops-plugin-h1b-sponsor/1.0';
const DEFAULT_TIMEOUT_MS = 10_000;
const MAX_RETRY_WAIT_MS = 10_000;
const MAX_REDIRECTS = 3;
// The largest real employer profile this API serves is about 13 KB and a search
// page is about 4 KB, so a megabyte is ~80x headroom for future growth while
// still refusing to buffer a runaway or hostile body.
const MAX_READ_BYTES = 1024 * 1024;

function buildHeaders(token) {
  const h = { 'Accept': 'application/json', 'User-Agent': USER_AGENT };
  if (typeof token === 'string' && token.trim()) {
    h['Authorization'] = `Bearer ${token.trim()}`;
  }
  return h;
}

function parseRetryAfter(res) {
  const raw = res.headers.get('retry-after');
  if (!raw) return 1_000;
  const secs = Number(raw);
  if (Number.isFinite(secs)) return Math.max(0, secs * 1000);
  const when = Date.parse(raw);
  if (Number.isFinite(when)) return Math.max(0, when - Date.now());
  return 1_000;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Exported so the mint CLI (token.mjs) sends its POST through the same egress
// guard the read path uses, rather than a bare fetch that would follow a
// redirect off-host with the freshly minted credential in the response.
// maxRedirects: same-host redirects re-issue the request with the SAME method
// and body, which is what a GET wants and what a mint POST must never do
// (each re-POST could spend mint budget again). The mint passes 0.
//
// allowedOrigins names where the request may end up. It defaults to the
// configured API base, so every existing caller keeps the same one-host guard;
// install-h1b-index.mjs passes its own list because a GitHub release download is
// answered by a different host than the one that serves the release metadata,
// and hard-coding apiBase() there would both refuse that hop and drag an
// unrelated H1B_API_BASE misconfiguration into a download that never touches
// the API. Resolved lazily inside the call so a caller that supplies the list
// never reads H1B_API_BASE at all.
//
// consume runs INSIDE the abort-timer window: a server that sends headers and
// then stalls the body would otherwise hang the caller forever, because the
// timer is cleared before the caller could parse. Callers that read the body
// must pass consume; the no-consume form returns the raw Response and is only
// safe when the body is never read.
export async function fetchWithTimeout(url, { headers = {}, timeoutMs = DEFAULT_TIMEOUT_MS, method = 'GET', body, maxRedirects = MAX_REDIRECTS, allowedOrigins } = {}, consume) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), timeoutMs);
  const allowed = (Array.isArray(allowedOrigins) && allowedOrigins.length > 0 ? allowedOrigins : [apiBase()])
    .map(o => new URL(o));
  try {
    // Egress guard: redirects are followed manually so an off-host target is
    // rejected BEFORE the request (and its query string) is issued to it.
    // Letting fetch follow redirects itself would send the request first and
    // only let us notice afterwards.
    let requestUrl = url;
    for (let hop = 0; ; hop++) {
      const res = await fetch(requestUrl, { method, headers, body, signal: controller.signal, redirect: 'manual' });
      if (res.status < 300 || res.status > 399) {
        return consume ? await consume(res) : res;
      }

      const loc = res.headers.get('location');
      // A 3xx without a Location header is not actionable (e.g. 304): hand it
      // back to the caller unchanged.
      if (!loc) return consume ? await consume(res) : res;

      const next = new URL(loc, requestUrl);
      // Host AND scheme must match: an http:// downgrade on the same host
      // would resend the Authorization header in cleartext.
      if (!allowed.some(a => a.host === next.host && a.protocol === next.protocol)) {
        const e = new Error(`H-1B API redirected off-host: ${next.protocol}//${next.host}`);
        e.code = 'REDIRECT_OFF_HOST';
        throw e;
      }
      if (hop >= maxRedirects) {
        const e = new Error(`H-1B API exceeded ${maxRedirects} redirects: ${url}`);
        e.code = 'REDIRECT_LOOP';
        throw e;
      }
      requestUrl = next.href;
    }
  } finally {
    clearTimeout(t);
  }
}

/**
 * Read a response body with a hard byte ceiling.
 *
 * `res.text()` and `res.json()` buffer the whole body first, so a size check
 * after the fact rejects an oversized value but never bounds what was already
 * allocated. This streams instead: it counts bytes as they arrive and cancels
 * the moment the total would exceed `maxBytes`, so peak memory stays bounded no
 * matter what the server sends. A Content-Length that already exceeds the cap
 * short-circuits the read, but the streaming count still runs because that
 * header can be absent or wrong.
 *
 * `maxBytes` is required and inclusive: a body of exactly `maxBytes` comes
 * back, one byte more does not. Returns `{ text }` when the body was read
 * whole, else `{ oversized: true }`, which marks a refused body, covering both
 * one past the ceiling and a chunk that cannot report a usable size, since
 * neither yields text a caller may trust. Read failures (including an
 * AbortError from the caller's timeout) propagate to the caller.
 */
export async function readBoundedText(res, maxBytes) {
  const declared = Number(res.headers?.get?.('content-length'));
  if (Number.isFinite(declared) && declared > maxBytes) {
    // Nothing here will be read, so release the body instead of leaving the
    // connection pinned until garbage collection.
    try { await res.body?.cancel?.(); } catch { /* nothing to release */ }
    return { oversized: true };
  }
  if (!res.body || typeof res.body.getReader !== 'function') {
    // Nothing to stream: a 204, or a response shim without a body. Measure the
    // buffered text in BYTES rather than UTF-16 units, because a length check
    // in code units lets a multibyte body past a byte ceiling, which is the
    // defect this function exists to close.
    const text = typeof res.text === 'function' ? await res.text() : '';
    const bytes = new TextEncoder().encode(text).byteLength;
    return bytes > maxBytes ? { oversized: true } : { text };
  }

  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!value) continue;
      const size = Number(value.byteLength);
      // A chunk that cannot report its own size would make the running total
      // NaN, and NaN never trips the ceiling below, so the read would run to
      // completion and hand back a truncated body as if it were whole. Refuse
      // it instead.
      if (!Number.isFinite(size)) {
        await reader.cancel().catch(() => {});
        return { oversized: true };
      }
      total += size;
      if (total > maxBytes) {
        await reader.cancel().catch(() => {});
        return { oversized: true };
      }
      chunks.push(value);
    }
  } finally {
    try { reader.releaseLock(); } catch { /* already released by cancel */ }
  }

  // Decode once over the joined bytes. Decoding per chunk would corrupt any
  // multibyte character split across a chunk boundary.
  const joined = new Uint8Array(total);
  let at = 0;
  for (const c of chunks) {
    joined.set(c, at);
    at += c.byteLength;
  }
  return { text: new TextDecoder('utf-8').decode(joined) };
}

async function requestJson(url, opts, { allow404 } = {}) {
  const token = opts.token;
  const timeoutMs = Number.isFinite(opts.timeoutMs) ? opts.timeoutMs : DEFAULT_TIMEOUT_MS;
  const headers = buildHeaders(token);

  // Every body read happens inside the fetch timer via consume, so a server
  // that sends headers and then stalls the body times out instead of hanging.
  // What comes back is a plain outcome object, never a live Response.
  const attempt = () => fetchWithTimeout(url, { headers, timeoutMs }, async res => {
    if (res.status === 429) return { kind: 'rate', waitMs: parseRetryAfter(res) };
    if (allow404 && res.status === 404) return { kind: 'missing' };
    if (!res.ok) {
      // An oversized error body is not worth reporting verbatim; the status
      // still tells the caller what happened, so drop the excerpt and continue.
      let text = '';
      try {
        const read = await readBoundedText(res, MAX_READ_BYTES);
        if (!read.oversized) text = read.text;
      } catch (err) {
        if (err && err.name === 'AbortError') throw err;
      }
      return { kind: 'http', status: res.status, statusText: res.statusText, text };
    }
    let read;
    try {
      read = await readBoundedText(res, MAX_READ_BYTES);
    } catch (err) {
      // A stalled body aborts on the shared timer and has to surface as the
      // timeout it is. Every other stream failure leaves an unusable body: a
      // reset or truncated response arrives as TypeError: terminated, and the
      // buffered res.json() this replaced reported exactly that case as
      // unparseable rather than letting a raw transport error escape.
      if (err && err.name === 'AbortError') throw err;
      return { kind: 'badjson' };
    }
    if (read.oversized) return { kind: 'toobig' };
    try {
      return { kind: 'json', body: JSON.parse(read.text) };
    } catch {
      return { kind: 'badjson' };
    }
  });

  const timeoutError = (label) => {
    const e = new Error(`H-1B API timeout${label} after ${timeoutMs}ms: ${url}`);
    e.code = 'TIMEOUT';
    return e;
  };

  let out;
  try {
    out = await attempt();
  } catch (err) {
    if (err && err.name === 'AbortError') throw timeoutError('');
    throw err;
  }

  if (out.kind === 'rate') {
    await sleep(Math.min(out.waitMs, MAX_RETRY_WAIT_MS));
    try {
      out = await attempt();
    } catch (err) {
      if (err && err.name === 'AbortError') throw timeoutError(' on retry');
      throw err;
    }
    if (out.kind === 'rate') {
      const e = new Error(`H-1B API rate limited: ${url}`);
      e.code = 'RATE_LIMIT';
      throw e;
    }
  }

  if (out.kind === 'missing') return null;

  if (out.kind === 'toobig') {
    const e = new Error(`H-1B API response exceeded ${MAX_READ_BYTES} bytes: ${url}`);
    e.code = 'BODY_TOO_LARGE';
    throw e;
  }

  if (out.kind === 'http') {
    const e = new Error(`H-1B API ${out.status} ${out.statusText}: ${url}${out.text ? ` -- ${out.text.slice(0, 200)}` : ''}`);
    e.code = 'HTTP_ERROR';
    e.status = out.status;
    throw e;
  }

  if (out.kind === 'badjson') {
    const e = new Error(`H-1B API returned non-JSON body: ${url}`);
    e.code = 'BAD_JSON';
    throw e;
  }

  return out.body;
}

// normalize, plausibleMatch and pickBestMatch are exported for lib/index.mjs,
// which resolves the same names against the local index. A second copy of these
// rules would drift, and they are the thing that stops "Meta" resolving to
// "Metabolic Diagnostics Inc", so the local backend imports them rather than
// reimplementing them, and a fix lands once for both.
export function normalize(str) {
  return String(str || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
}

// Long legal-form words folded to their short form, so "corporation" and
// "corp" become one token. Deleting the suffix instead was wrong: it collapsed
// "Acme LLC" and "Acme Inc" to a bare "acme" and matched two distinct entities.
// Canonicalizing keeps the form as a token, so different forms (llc vs inc)
// stay different while a single form's long and short spellings unify, which is
// exactly what the maintainer asked for (fold corp/corporation, nothing more).
const SUFFIX_CANON = new Map([
  ['corporation', 'corp'],
  ['incorporated', 'inc'],
  ['limited', 'ltd'],
  ['company', 'co'],
]);

// Guard against the search endpoint's nearest-neighbour behavior: it returns
// its closest hit even for garbage input. A fallback (non-exact) match is
// accepted only when one name's token list is a prefix of the other's, token
// for token: "IBM" matches "IBM Corporation", and "Microsoft Corporation"
// matches "Microsoft", but "Meta" does not match "Metabolic Diagnostics Inc"
// (substring tests did, which cached a confidently wrong employer for 90
// days). No plausible candidate -> no match, and the CLI reports unknown.
export function plausibleMatch(query, candidateName) {
  // Normalize both names, then compare token for token, one list against the
  // start of the other. A leading "the" is dropped ("Home Depot" must match
  // "The Home Depot"). A trailing long-form legal word is folded to its short
  // form, so "Acme Corp" matches "Acme Corporation" (the JD spells the short
  // form where DOL records the long one, and that miss used to stick in the
  // 30-day negative cache). Folding rather than deleting keeps the form as a
  // token, so "Apple Inc" does not swallow "Apple Bank" and "Acme LLC" stays
  // distinct from "Acme Inc"; the exact-normalized check in pickBestMatch still
  // catches two identical names first.
  const tokens = s => {
    const t = String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
    // A dotted or spaced initialism arrives as a run of one-letter tokens
    // ("I.B.M." splits to i, b, m) while the filer spells it joined ("IBM
    // Corporation"), so a run of two or more one-letter tokens folds into
    // one. A lone one-letter token stays as it is: "Meta 4 LLC" keeps its 4
    // and "AT&T" its trailing t, so the fold unifies initialisms without
    // loosening anything else.
    const merged = [];
    for (let i = 0; i < t.length; i++) {
      let j = i;
      while (t[j].length === 1 && j + 1 < t.length && t[j + 1].length === 1) j++;
      if (j > i) { merged.push(t.slice(i, j + 1).join('')); i = j; } else { merged.push(t[i]); }
    }
    const out = merged[0] === 'the' ? merged.slice(1) : merged.slice();
    if (out.length > 0) {
      const canon = SUFFIX_CANON.get(out[out.length - 1]);
      if (canon) out[out.length - 1] = canon;
    }
    return out;
  };
  const q = tokens(query);
  const c = tokens(candidateName);
  if (q.length === 0 || c.length === 0) return false;
  const isPrefix = (shorter, longer) =>
    shorter.length <= longer.length && shorter.every((t, i) => t === longer[i]);
  return isPrefix(q, c) || isPrefix(c, q);
}

export function pickBestMatch(name, results) {
  if (!Array.isArray(results) || results.length === 0) return null;
  const target = normalize(name);
  // 1. Exact normalized match.
  const exact = results.find(r => r && normalize(r.name) === target);
  if (exact) return exact;
  // 2. First PLAUSIBLE result, wherever it sits in the list. This used to look
  // at results[0] alone and lean on the search endpoint having ranked the page
  // for us. The local index has no ranking to lean on, since its candidates
  // come out in file order, so a rank-dependent rule would resolve a name over
  // HTTP and fail to resolve the same name locally. plausibleMatch is what
  // keeps this honest: an implausible candidate is still refused no matter
  // where it sits.
  const plausible = results.find(r => r && plausibleMatch(name, r.name));
  if (plausible) return plausible;
  return null;
}

export async function resolveEmployer(name, opts = {}) {
  const q = String(name || '').trim();
  if (q.length < 2) return null;

  const url = `${apiBase()}/employers/search?q=${encodeURIComponent(q)}`;
  const body = await requestJson(url, opts, { allow404: true });
  if (!body) return null;

  const results = Array.isArray(body.results) ? body.results : [];
  const match = pickBestMatch(q, results);
  if (!match || !match.id) return null;

  return { id: String(match.id), displayName: String(match.name || q) };
}

// Every matching employer the API returns, not just the best pick, so a broad
// name like "Amazon" surfaces each distinct filing entity (they file under
// separate FEINs and the numbers differ). Returns { total, results }; total is
// the API's full count, which can exceed the page the endpoint returns, so the
// caller can tell the user to narrow the query. [] results on no match or a
// soft failure.
export async function searchEmployers(name, opts = {}) {
  const q = String(name || '').trim();
  if (q.length < 2) return { total: 0, results: [] };

  const url = `${apiBase()}/employers/search?q=${encodeURIComponent(q)}`;
  const body = await requestJson(url, opts, { allow404: true });
  if (!body || !Array.isArray(body.results)) return { total: 0, results: [] };

  const results = body.results
    .filter(r => r && r.id)
    .map(r => ({ id: String(r.id), name: String(r.name || '') }));
  const total = Number.isFinite(body.total) ? body.total : results.length;
  return { total, results };
}

// Number(null) === 0 and Number(' ') === 0, so a null or blank field would
// otherwise look like a real zero. Exported for the same reason as the matchers
// above: lib/index.mjs builds the identical profile shape from index records,
// and null-vs-zero is exactly the distinction a second copy would get wrong.
export function num(v) {
  if (v === null || v === undefined || (typeof v === 'string' && v.trim() === '')) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

// Normalizes the nested API envelope into the flat shape that tier.mjs and
// check.mjs expect. Missing fields stay null / 0 -- never invented.
function normalizeProfile(raw) {
  if (raw == null || typeof raw !== 'object') return raw;
  const employer = (raw.employer && typeof raw.employer === 'object') ? raw.employer : {};
  const years = (raw.years && typeof raw.years === 'object') ? raw.years : {};
  const filings = (raw.filings && typeof raw.filings === 'object') ? raw.filings : {};
  const gc = (raw.green_card && typeof raw.green_card === 'object') ? raw.green_card : {};
  const redFlagsRaw = (raw.red_flags && typeof raw.red_flags === 'object') ? raw.red_flags : {};
  const staffing = (redFlagsRaw.staffing_shop && typeof redFlagsRaw.staffing_shop === 'object')
    ? redFlagsRaw.staffing_shop
    : null;

  const nPwd = num(gc.pwd);
  const nPerm = num(gc.perm);
  const evidence = gc.evidence;
  // does_gc: true when the API reports green-card evidence 'present', or when
  // any GC filings exist (pwd/perm > 0). Anything else is false, not null,
  // because tier.mjs compares strictly against `=== true`.
  const doesGc = evidence === 'present'
    || (nPwd !== null && nPwd > 0)
    || (nPerm !== null && nPerm > 0);

  // A missing/null year stays null: it must never collapse to year 0.
  const firstYear = num(years.first);
  const lastYear = num(years.last);

  // LCA volume is a separate track from the green_card block (an employer can
  // be LCA-active with zero GC filings). The count is the RAW filing total:
  // filing an LCA is the employer's own act of willingness to sponsor, which
  // is the question being asked here. Whether a given filing was certified is
  // USCIS's decision, and a withdrawal is usually the candidate taking another
  // offer or a cancelled req, so neither says this employer will not sponsor.
  // Preferring `certified`, which is what this used to do, reported 3,777
  // employers in the 2026Q2 data as tier `none` (the phrase the skill prints
  // for "the DOL data shows nothing") despite their having filed.
  //
  // certified stays as the fallback so a payload from an API old enough to
  // omit `lca` still answers. The fallback runs on null, never on 0, so a real
  // zero is not masked the way `Number(null) === 0` did.
  const nCertified = num(filings.certified);
  const nLcaTotal = num(filings.lca);
  const nLca = nLcaTotal ?? nCertified ?? 0;

  return {
    n_lca: nLca ?? 0,
    // The outcome, carried through for display beside the filing count. Null
    // rather than 0 when the payload does not report it: "not reported" and
    // "reported as none certified" are different statements, and the skill
    // prints them differently.
    n_certified: nCertified ?? null,
    n_pwd: nPwd ?? 0,
    n_perm: nPerm ?? 0,
    does_gc: doesGc === true,
    first_year: firstYear,
    last_year: lastYear,
    red_flags: {
      staffing_shop: staffing
        ? {
            value: staffing.value === true,
            share: typeof staffing.share === 'number' ? staffing.share : null,
            n_secondary: staffing.n_secondary ?? null,
            n_total: staffing.n_total ?? null,
            basis: staffing.basis ?? null,
          }
        : null,
    },
    employer_name: employer.name ?? null,
    employer_id: employer.id ?? employer.ein ?? null,
  };
}

export async function getEmployerProfile(id, opts = {}) {
  const sanitized = String(id || '').trim();
  if (!sanitized) throw new Error('getEmployerProfile: id is required');
  const url = `${apiBase()}/employers/${encodeURIComponent(sanitized)}`;
  const raw = await requestJson(url, opts, { allow404: false });
  return normalizeProfile(raw);
}

// Filesystem cache for H-1B sponsor lookups.
// One JSON file per company under {cacheDir}/{cacheKey(name)}.json.
// Positive entries default TTL 90d, negative (unresolved names) default 30d.

import { mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';

// Anchored to the repo root, not process.cwd(): running the CLI from another
// directory must reuse the one cache tree instead of creating a stray one and
// re-burning the 30/hr anonymous budget. cache.mjs lives at
// plugins/h1b-sponsor/lib/, so three levels up is the repo root.
const DEFAULT_DIR = fileURLToPath(new URL('../../../data/cache/h1b', import.meta.url));
const DEFAULT_TTL_DAYS = 90;
const DEFAULT_NEG_TTL_DAYS = 30;
const DAY_MS = 86_400_000;

// The slug is bounded (long employer names would otherwise blow past
// ENAMETOOLONG) and suffixed with a digest of the full name so that distinct
// names which slugify identically ("AB C" vs "A BC") get distinct entries.
export function cacheKey(name) {
  const raw = typeof name === 'string' ? name : '';
  const slug = raw.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  const digest = createHash('sha256').update(raw.toLowerCase().trim()).digest('hex').slice(0, 8);
  return `${(slug || 'noname').slice(0, 80)}-${digest}`;
}

function entryPath(cacheDir, name) {
  return path.join(cacheDir, `${cacheKey(name)}.json`);
}

export async function readCache(name, opts = {}) {
  const cacheDir = opts.cacheDir ?? DEFAULT_DIR;
  const ttlDays = Number.isFinite(opts.ttlDays) ? opts.ttlDays : DEFAULT_TTL_DAYS;
  const negTtlDays = Number.isFinite(opts.negativeTtlDays) ? opts.negativeTtlDays : DEFAULT_NEG_TTL_DAYS;

  let raw;
  try {
    raw = await readFile(entryPath(cacheDir, name), 'utf8');
  } catch {
    return null;
  }

  let entry;
  try {
    entry = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!entry || typeof entry !== 'object' || typeof entry.fetchedAt !== 'string') return null;
  // A well-formed entry always carries a data payload (writeCache guarantees
  // it): an entry without one is malformed, so fail closed.
  if (!('data' in entry)) return null;

  const fetchedAt = Date.parse(entry.fetchedAt);
  if (!Number.isFinite(fetchedAt)) return null;

  const age = Date.now() - fetchedAt;
  // A future fetchedAt is clock skew or tampering; either way not usable.
  if (age < 0) return null;

  const ttl = entry.negative === true ? negTtlDays : ttlDays;
  if (age > ttl * DAY_MS) return null;

  return entry;
}

export async function writeCache(name, data, opts = {}) {
  const cacheDir = opts.cacheDir ?? DEFAULT_DIR;
  const negative = opts.negative === true;

  await mkdir(cacheDir, { recursive: true });

  // The caller may pin the timestamp it already printed, so a later warm
  // read serves back exactly the bytes the original run reported.
  const fetchedAt = typeof opts.fetchedAt === 'string' ? opts.fetchedAt : new Date().toISOString();
  const entry = { data, fetchedAt };
  if (negative) entry.negative = true;

  const finalPath = entryPath(cacheDir, name);
  const tmpPath = `${finalPath}.${randomUUID()}.tmp`;
  try {
    await writeFile(tmpPath, JSON.stringify(entry, null, 2), 'utf8');
    await rename(tmpPath, finalPath);
  } catch (err) {
    // Never leave a half-written .tmp behind; surface the original failure.
    await unlink(tmpPath).catch(() => {});
    throw err;
  }
  return entry;
}

// Local backend for the H-1B sponsorship check: same three functions as
// lib/api.mjs, answered from a gzipped NDJSON index on disk instead of an HTTP
// endpoint. This is the default path, and the reason is the query rather than
// the answer: asking whether a company sponsors says that the person asking
// needs a visa and names the employers they are considering. Over HTTP that
// leaves the machine and reaches whoever runs the endpoint. Here it does not
// leave the machine at all.
//
// The data is the same public DOL disclosure material the API serves, built
// into one file per release. Matching rules are imported from lib/api.mjs
// rather than restated, so both backends resolve a name identically.

import { createReadStream, existsSync, statSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { createGunzip } from 'node:zlib';
import { createInterface } from 'node:readline';
import { fileURLToPath } from 'node:url';
import { normalize, num, pickBestMatch, plausibleMatch } from './api.mjs';

// Anchored to the repo root for the same reason lib/cache.mjs is: running the
// CLI from another directory must find the one installed index rather than
// report it missing. lib/ sits three levels below the root.
//
// Its own directory, deliberately not the data/cache/h1b/ tree the lookup cache
// lives in. That tree is documented as safe to delete at any time and it is:
// every file in it is a disposable answer the next lookup would rebuild. The
// index is not disposable in that sense. It is an 8 MiB artifact the user chose
// to install, over the network, in a command they had to run themselves, and
// re-creating it means doing that again. Filing it under "cache" invites a
// cleanup that silently disables the plugin.
const DEFAULT_INDEX = fileURLToPath(new URL('../../../data/h1b/index.ndjson.gz', import.meta.url));

// The staffing-shop numbers in an index record are the secondary-worksite
// counts the API reports under this basis. It is a constant here because the
// index carries one measure; the field exists so a consumer can tell which.
const STAFFING_BASIS = 'secondary_entity_share';

// What --search shows at once. Mirrors the page the HTTP endpoint serves, so
// the CLI's "narrow the query to see the rest" header means the same thing on
// both backends.
const SEARCH_PAGE = 50;

// Ceiling on how many non-exact candidates a resolve keeps. Without it a bare
// query like "American" would hold every employer with that leading token in
// memory to pick one (1,401 for "New" in the shipped index). What the cap drops
// is decided by rank, not by arrival: see boundedTop.
const MAX_CANDIDATES = 500;

/**
 * The order the API publishes its search buckets in: descending sponsorship
 * evidence, then name, then key. The HTTP backend's results arrive already
 * sorted this way and pickBestMatch leans on it, taking the first exact match
 * and otherwise the first plausible one, so the highest-volume match is what it
 * lands on.
 *
 * Records come off the index in the publisher's NAME order instead, so without
 * this the alphabet decides the answer and a zero-filing lookalike beats the
 * company being asked about: "Meta" resolved to "META 4 LLC" (0 LCAs) over
 * "Meta Platforms, Inc" (38,117), "Google" to "Google Client Services LLC" (2)
 * over "Google LLC" (70,985). A tier of `none` for an employer that filed
 * 38,117 LCAs is precisely the confident wrong answer this plugin exists to
 * prevent, so the local candidate list is sorted into the server's order and
 * both backends resolve a name identically again.
 *
 * The key is the same sum classifyTier adds up, filings plus the two green card
 * steps, and etl/publish.py's search_volume() now ranks the server's buckets by
 * that same sum. Ranking on any narrower number lets resolution seat an entity
 * ahead of a same-named sibling that has more evidence than it does: measured
 * on the 2026Q2 build, grouped the way this file matches names, ranking by
 * certified alone did that for 6,929 shared-name groups and by raw LCA count
 * alone for 6,617 (the publisher counts the same failure against its own bucket
 * normalization, which is why its numbers differ). Most of them are the 156,616
 * employers with green card filings and no LCA rows at all, which carry zero
 * volume under either single number and rank correctly under this one.
 *
 * Plain `<` on the tie-breakers rather than localeCompare: the publisher sorts
 * in Python, whose string comparison is by code point and does not move with a
 * locale.
 */
function evidence(rec) {
  return (num(rec && rec.filed) ?? 0) + (num(rec && rec.pwd) ?? 0) + (num(rec && rec.perm) ?? 0);
}

function byRank(a, b) {
  const av = evidence(a);
  const bv = evidence(b);
  if (av !== bv) return bv - av;
  const an = String((a && a.n) ?? '');
  const bn = String((b && b.n) ?? '');
  if (an !== bn) return an < bn ? -1 : 1;
  const ak = String((a && a.k) ?? '');
  const bk = String((b && b.k) ?? '');
  if (ak === bk) return 0;
  return ak < bk ? -1 : 1;
}

/**
 * A list that keeps only the top `limit` records under byRank as a scan runs.
 *
 * Bounded because a broad query can match a large share of the file: the
 * two-character "in" is inside 193,292 of the shipped index's normalized names.
 * Trimmed by rank rather than by arrival because arrival order is name order,
 * and keeping the first N would put the alphabet back in charge of which
 * matches survive to be ranked, which is the defect byRank exists to remove.
 */
function boundedTop(limit) {
  const items = [];
  const trim = () => {
    items.sort(byRank);
    if (items.length > limit) items.length = limit;
  };
  return {
    push(rec) {
      items.push(rec);
      if (items.length >= limit * 2) trim();
    },
    drain() {
      trim();
      return items;
    },
  };
}

/**
 * Where the index lives. H1B_INDEX_PATH relocates it (a shared read-only copy,
 * a scratch fixture in the test suite). Present-but-blank is a misconfiguration
 * rather than "unset", exactly as H1B_API_BASE treats it: silently falling back
 * would read an index the user believed they had replaced.
 */
export function indexPath() {
  const raw = process.env.H1B_INDEX_PATH;
  if (raw === undefined) return DEFAULT_INDEX;
  const trimmed = String(raw).trim();
  if (!trimmed) {
    throw new Error('H1B_INDEX_PATH is set but empty. Unset it to use the default index location.');
  }
  return trimmed;
}

/** The sidecar install-h1b-index.mjs writes beside the index. */
export function metaPath(file = indexPath()) {
  return `${file}.meta.json`;
}

/** Whether a local index is installed. Decides the backend, so it never throws on a missing file. */
export function hasIndex(file = indexPath()) {
  return existsSync(file);
}

const SHA256_RE = /^[0-9a-f]{64}$/;
let cachedDigest = null;

/**
 * Digest of the installed index, used as the provenance stamp on cached
 * answers. The sidecar carries the digest install-h1b-index.mjs verified before it
 * moved the file into place, which saves re-hashing 8 MiB on every lookup; it
 * is trusted only when it still describes a file of that size, so an index
 * swapped underneath a stale sidecar gets hashed rather than mislabelled.
 */
export async function indexDigest(file = indexPath()) {
  if (cachedDigest && cachedDigest.file === file) return cachedDigest.digest;

  let size;
  try {
    size = statSync(file).size;
  } catch {
    const e = new Error(`H-1B index not found: ${file}`);
    e.code = 'INDEX_MISSING';
    throw e;
  }

  let digest = null;
  try {
    const meta = JSON.parse(await readFile(metaPath(file), 'utf8'));
    if (meta && SHA256_RE.test(String(meta.sha256)) && Number(meta.bytes) === size) {
      digest = String(meta.sha256);
    }
  } catch { /* no sidecar, or an unreadable one: hash the file instead */ }

  if (!digest) {
    const hash = createHash('sha256');
    for await (const chunk of createReadStream(file)) hash.update(chunk);
    digest = hash.digest('hex');
  }

  cachedDigest = { file, digest };
  return digest;
}

/**
 * How an answer from this backend is labelled: in the `source` field of the
 * CLI output, and as the provenance key on its cache entry. Naming the digest
 * rather than the file path is what makes a refreshed index invalidate the
 * answers the previous one produced.
 */
export async function indexSource(file = indexPath()) {
  return `local:h1b-index@sha256-${(await indexDigest(file)).slice(0, 12)}`;
}

/**
 * Stream the index one record at a time.
 *
 * Whole-file scan by design, and the name-matching callers read to the end.
 * The index is a single gzip member, so there is no seeking into it, and
 * neither resolve nor search can stop
 * early: the file is ordered by the publisher's normalizer rather than this
 * one, so passing the query alphabetically proves nothing, and a match found
 * part-way through can still be beaten on filing volume by one further down
 * (see byRank). Measured on the shipped 335,626-record index, a lookup costs
 * ~1.9s against a ~0.95s floor for decompressing and splitting lines with no
 * work on top. Parsing every line is inside that floor's noise (~1.1s), which
 * is why there is no substring pre-filter ahead of JSON.parse: every cheap one
 * is either unsound (a raw-text filter
 * drops "I.B.M." for a query of "IBM", because normalization removes the dots
 * that the raw text still has) or, once made sound by normalizing the line
 * first, slower than the parse it was avoiding.
 *
 * A line that does not parse is skipped rather than fatal: a truncated tail is
 * a reason to lose one employer, not to fail the lookup. A source or gunzip
 * failure is fatal and surfaces as INDEX_UNREADABLE.
 *
 * A record without a `filed` field is skipped by the same rule. That is what a
 * line in the pre-release index shape looks like, the one that carried a single
 * `lca` field resolved to the certified count: reading its numbers into the
 * current fields would report an employer's certifications as its filings and
 * every green card only employer as having no evidence. Nothing has to migrate
 * such a file, because the source stamp is the index digest and the digest of a
 * rebuilt index is different, so its cached answers are already invalid.
 */
async function* readRecords(file) {
  const source = createReadStream(file);
  const gunzip = createGunzip();
  // .pipe() does not forward errors, so without this a missing or unreadable
  // file leaves gunzip waiting for an end that never comes and the iterator
  // below hangs instead of failing.
  source.on('error', err => gunzip.destroy(err));
  const rl = createInterface({ input: source.pipe(gunzip), crlfDelay: Infinity });
  try {
    for await (const line of rl) {
      if (!line) continue;
      let rec;
      try {
        rec = JSON.parse(line);
      } catch {
        continue;
      }
      if (rec && typeof rec === 'object' && typeof rec.n === 'string' && num(rec.filed) !== null) yield rec;
    }
  } catch (err) {
    const e = new Error(`H-1B index unreadable (${file}): ${err && err.message ? err.message : err}`);
    e.code = 'INDEX_UNREADABLE';
    throw e;
  } finally {
    // A caller that breaks out of the loop lands here. Closing the interface
    // alone leaves the file handle open, so tear down the whole chain.
    rl.close();
    gunzip.destroy();
    source.destroy();
  }
}

// Records already read this process. check.mjs resolves a name and then reads
// that employer's profile; without this the second call would scan the same
// file again for a record the first call already had. Keyed by file as well as
// id: a process that reads two different indexes (the test suite does) must not
// answer from the wrong one.
const seen = new Map();
const memoKey = (file, id) => `${file}\u0000${id}`;

function indexFile(opts) {
  return opts.indexPath || indexPath();
}

// The same flat profile lib/api.mjs produces from the HTTP envelope, so
// classifyTier and the CLI's output builder cannot tell the backends apart.
// The index publishes the two filing numbers separately, `filed` and `cert`,
// which is the same pair the API reports as filings.lca and filings.certified;
// the tier reads the first and the report prints both.
function recordToProfile(rec) {
  const nPwd = num(rec.pwd) ?? 0;
  const nPerm = num(rec.perm) ?? 0;
  return {
    n_lca: num(rec.filed) ?? 0,
    // Null, not 0, when the record does not carry it: "not reported" is not
    // "none certified". Every published build carries it.
    n_certified: num(rec.cert) ?? null,
    n_pwd: nPwd,
    n_perm: nPerm,
    // The same belt the HTTP path wears in normalizeProfile: the gc flag, or
    // any GC filing at all. Every published build already satisfies the
    // implication (zero rows carry filings without the flag), so this changes
    // no answer today; it keeps the backends agreeing by construction if the
    // upstream flag ever drifts from the counts it summarizes.
    does_gc: rec.gc === true || nPwd > 0 || nPerm > 0,
    first_year: num(rec.fy),
    last_year: num(rec.ly),
    red_flags: {
      staffing_shop: {
        value: rec.sv === true,
        share: typeof rec.sh === 'number' ? rec.sh : null,
        n_secondary: num(rec.ns),
        // The share's denominator is the filing count, so the index stopped
        // shipping it a second time under its own field: sql/03_populate.sql
        // builds the block as n_secondary / n_lca, and `filed` IS n_lca.
        n_total: num(rec.filed),
        basis: STAFFING_BASIS,
      },
    },
    employer_name: rec.n ?? null,
    employer_id: rec.k ?? null,
  };
}

export async function resolveEmployer(name, opts = {}) {
  const q = String(name || '').trim();
  if (q.length < 2) return null;

  const file = indexFile(opts);
  const target = normalize(q);
  const exact = [];
  const plausible = boundedTop(MAX_CANDIDATES);
  // Read to the end rather than stopping at the first exact name. Distinct
  // employers share a normalized name often (40,635 groups in the shipped
  // index) and the volumes inside a group are not close: stopping at the first
  // one took "Amazon.com Services LLC" at 1 LCA over the 92,132-LCA entity of
  // the same name, and "Bank of America N.A." at 0 over 5,142. The scan has to
  // see every one of them for byRank to pick the same record the API would.
  for await (const rec of readRecords(file)) {
    const isExact = normalize(rec.n) === target;
    if (!isExact && !plausibleMatch(q, rec.n)) continue;
    seen.set(memoKey(file, rec.k), rec);
    // Exact names are kept whole rather than rank-trimmed. There are few of
    // them (58 in the widest group of the shipped index) and one can carry a
    // low filing count, which the plausible pool is right to drop and this one
    // is not: an exact name wins its tier outright in pickBestMatch, so losing
    // it to a volume trim would hand the answer to a merely plausible name.
    if (isExact) exact.push(rec);
    else plausible.push(rec);
  }

  // One list in the order the API publishes its search buckets, so
  // pickBestMatch reaches the same record on both backends: exact normalized
  // name first, else the first plausible one, each now the highest-volume of
  // its kind rather than the alphabetically earliest.
  const candidates = [...exact, ...plausible.drain()].sort(byRank);
  const match = pickBestMatch(q, candidates.map(r => ({ id: String(r.k), name: String(r.n) })));
  if (!match || !match.id) return null;
  return { id: String(match.id), displayName: String(match.name || q) };
}

// Every entity whose name contains the query, not just the best pick, so a
// broad name like "Amazon" surfaces each distinct filing entity (they file
// under separate FEINs and the numbers differ). Substring rather than the
// prefix rule resolveEmployer uses: this is the command someone runs when the
// exact legal name is what they are missing. `total` counts every match so the
// caller can say how much the page is hiding.
export async function searchEmployers(name, opts = {}) {
  const q = String(name || '').trim();
  if (q.length < 2) return { total: 0, results: [] };

  const target = normalize(q);
  const page = boundedTop(SEARCH_PAGE);
  let total = 0;
  for await (const rec of readRecords(indexFile(opts))) {
    if (!normalize(rec.n).includes(target)) continue;
    total++;
    page.push(rec);
  }
  // Same order the endpoint pages in, so the one page a broad query shows holds
  // the entities that actually file rather than the ones that sort first.
  return { total, results: page.drain().map(r => ({ id: String(r.k), name: String(r.n) })) };
}

export async function getEmployerProfile(id, opts = {}) {
  const sanitized = String(id || '').trim();
  if (!sanitized) throw new Error('getEmployerProfile: id is required');

  const file = indexFile(opts);
  const memo = seen.get(memoKey(file, sanitized));
  if (memo) return recordToProfile(memo);

  for await (const rec of readRecords(file)) {
    if (String(rec.k) !== sanitized) continue;
    seen.set(memoKey(file, sanitized), rec);
    return recordToProfile(rec);
  }
  // The HTTP path 404s here and reports the same thing: an id that resolves to
  // no employer is unknown, not an employer with zero filings.
  return null;
}

// Pure tier classifier for an employer profile.
// Contract: takes the normalized profile from getEmployerProfile() (or null)
// and returns one of: 'strong' | 'moderate' | 'staffing-shop' | 'weak' | 'none' | 'unknown'.
// Rules applied in order, first match wins. No I/O, no side effects.

export function classifyTier(profile) {
  if (profile == null || typeof profile !== 'object') return 'unknown';

  const staffing = profile.red_flags && profile.red_flags.staffing_shop;
  if (staffing && staffing.value === true) return 'staffing-shop';

  const nPwd = Number(profile.n_pwd ?? 0) || 0;
  const nPerm = Number(profile.n_perm ?? 0) || 0;
  // LCA volume (n_lca) is a separate track from GC filings (n_pwd/n_perm):
  // an employer can be LCA-active with zero GC filings, and cached profiles
  // written before n_lca existed simply contribute 0 here.
  const nLca = Number(profile.n_lca ?? 0) || 0;
  const total = nLca + nPwd + nPerm;

  if (total === 0) return 'none';

  const currentYear = new Date().getUTCFullYear();
  const lastYear = Number(profile.last_year);
  const hasLastYear = Number.isFinite(lastYear);

  const stale = hasLastYear && lastYear < currentYear - 3;
  const lowVolume = total < 5;
  if (stale || lowVolume) return 'weak';

  // Coerce share numerically: a legacy/hand-edited cache entry can carry the
  // share as a string, and typeof-gating would silently read "0.9" as absent.
  const shareNum = staffing ? Number(staffing.share) : NaN;
  const staffingShare = Number.isFinite(shareNum) ? shareNum : null;
  // Bounded above: a last_year further out than next year is API drift, not a
  // recent filing record.
  const recent = hasLastYear && lastYear >= currentYear - 2 && lastYear <= currentYear + 1;

  // Strong: has GC evidence, recent, staffing share < 0.2 (a missing
  // staffing_shop block or non-numeric share counts as 0, matching the
  // moderate branch's treatment).
  if (profile.does_gc === true && recent && (staffingShare ?? 0) < 0.2) {
    return 'strong';
  }

  // Moderate: LCA volume >= 5, recent, staffing_shop.share < 0.5
  // (missing staffing_shop block treated as share 0, matching the strong branch).
  if (total >= 5 && recent && (staffingShare ?? 0) < 0.5) {
    return 'moderate';
  }

  return 'weak';
}

#!/usr/bin/env node
// Self-serve API key request for the H-1B sponsor check.
// Usage: node plugins/h1b-sponsor/token.mjs request
//
// Prints a new token to stdout and stops there. It never writes .env, never
// writes any other file, and never prints the token anywhere but that one
// block: where a durable credential gets stored is the user's call.
//
// Minting is metered per address, so a 429 here is that budget working rather
// than an outage.

import { isMainModule } from '../../lib/is-main-module.mjs';
import { apiBase, fetchWithTimeout, readBoundedText } from './lib/api.mjs';

const USER_AGENT = 'career-ops-plugin-h1b-sponsor/1.0';
const TIMEOUT_MS = 10_000;
const USAGE = 'Usage: node plugins/h1b-sponsor/token.mjs request';
// A real token is h1b_ followed by hex. Anything else must not reach the
// H1B_API_TOKEN= line: a value carrying shell metacharacters would run when the
// user sources their .env.
const TOKEN_RE = /^h1b_[0-9a-f]+$/;
// Server-controlled text printed to the terminal gets the same control-char
// strip check.mjs applies: C0, DEL, and C1, then whitespace collapse.
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS = /[\u0000-\u001f\u007f-\u009f]/g;
function displayClean(s) {
  // Whitespace collapse first: newlines are control chars too, and stripping
  // them before the collapse would glue words together instead of separating
  // them. What survives (ESC, BEL, DEL, C1) is not whitespace and is stripped.
  return String(s || '').replace(/\s+/g, ' ').replace(CONTROL_CHARS, '').trim();
}

// "about 12 hours" is something a person can act on; the raw 43200 reads like
// an error code.
function humanSpan(seconds) {
  const s = Math.max(0, Math.round(seconds));
  const span = (n, unit) => `about ${n} ${unit}${n === 1 ? '' : 's'}`;
  if (s < 60) return span(Math.max(1, s), 'second');
  if (s < 3600) return span(Math.round(s / 60), 'minute');
  if (s < 86_400) return span(Math.round(s / 3600), 'hour');
  return span(Math.round(s / 86_400), 'day');
}

// A mint reply is a small JSON object; anything bigger is not a key service
// answering. readBoundedText counts bytes as they stream in and cancels once
// the total would pass this, so the cap bounds the read itself and peak memory,
// not just what gets parsed.
const MAX_BODY_BYTES = 64 * 1024;

// The mint POST goes through the read path's egress guard (redirect handled
// manually, off-host or scheme-downgraded targets rejected) so a hijacked
// redirect cannot hand back an attacker-issued token. maxRedirects is 0: the
// key service never redirects this endpoint, and following one would re-issue
// the POST, which could spend the mint budget more than once. The body is read
// inside the same abort-timer window (via consume) so a server that sends
// headers and then stalls the body cannot hang the CLI. Such a stall is
// reported against the status that already arrived rather than as a timeout
// (see consume below). The read is size-capped. What comes back is a plain
// envelope, never a live Response: { status, retryAfterSeconds, body |
// bodyError }.
function guardedMintFetch() {
  return fetchWithTimeout(`${apiBase()}/keys/request`, {
    method: 'POST',
    headers: { 'Accept': 'application/json', 'User-Agent': USER_AGENT },
    timeoutMs: TIMEOUT_MS,
    maxRedirects: 0,
  }, async res => {
    const rawRetry = res.headers.get('retry-after');
    const retrySecs = Number(rawRetry);
    const envelope = {
      status: res.status,
      retryAfterSeconds: (rawRetry !== null && Number.isFinite(retrySecs)) ? retrySecs : null,
    };
    let read;
    try {
      read = await readBoundedText(res, MAX_BODY_BYTES);
    } catch {
      // Headers are already in hand: consume only runs once fetch has resolved,
      // so the status is known and true even when the body never arrives. Keep
      // it rather than reporting a bare timeout, which reads as "nothing
      // happened". That matters most on a 201, where it would invite a retry
      // that spends another of the day's two mints, but it is equally wrong on
      // a 429 (the wait is already known from the headers) or a 500. A real
      // timeout before any headers still surfaces as one, because consume never
      // runs for it.
      envelope.bodyError = 'unreadable';
      return envelope;
    }
    if (read.oversized) {
      envelope.bodyError = 'oversized';
      return envelope;
    }
    try {
      envelope.body = JSON.parse(read.text);
    } catch {
      envelope.bodyError = 'notjson';
    }
    return envelope;
  });
}

/**
 * Request one key. Returns a plain result so the outcome is testable without a
 * live mint: `{ ok: true, token, note }` on success, else
 * `{ ok: false, exitCode, message }`. `fetchImpl` is injectable for tests and
 * must resolve to the envelope shape guardedMintFetch produces.
 */
export async function mintToken({ fetchImpl = guardedMintFetch } = {}) {
  let env;
  try {
    env = await fetchImpl();
  } catch (err) {
    const reason = (err && err.name === 'AbortError')
      ? `no response within ${TIMEOUT_MS / 1000}s`
      : displayClean((err && err.message) ? err.message : err);
    return { ok: false, exitCode: 1, message: `could not reach the key service (${reason})` };
  }

  if (env.status === 429) {
    const span = (env.retryAfterSeconds !== null) ? humanSpan(env.retryAfterSeconds) : null;
    return {
      ok: false,
      exitCode: 1,
      message: `rate limited: this address has used its recent mint budget (2 available, then one more every 12 hours). Try again in ${span || 'a while'}.`,
    };
  }

  if (env.status !== 201) {
    return { ok: false, exitCode: 1, message: `could not issue a key (HTTP ${env.status})` };
  }

  // A 201 means the server may already have spent this address's budget, so a
  // failure to read the token past that point is worth saying out loud.
  const spentNote = ' A key may have been issued and the mint budget spent; wait for the cool-off before retrying.';

  if (env.bodyError || !env.body) {
    return { ok: false, exitCode: 1, message: `could not issue a key (the response was not readable JSON).${spentNote}` };
  }

  const body = env.body;
  const token = (typeof body.token === 'string') ? body.token.trim() : '';
  if (!token) {
    return { ok: false, exitCode: 1, message: `could not issue a key (the response carried no token).${spentNote}` };
  }
  if (!TOKEN_RE.test(token)) {
    return { ok: false, exitCode: 1, message: `could not issue a key (the response token was malformed).${spentNote}` };
  }

  // Server-controlled text; collapse whitespace so it stays one line and cannot
  // smuggle extra instructions into output the agent may relay.
  const note = (typeof body.note === 'string') ? displayClean(body.note) : '';

  return { ok: true, token, note };
}

function render(result) {
  // The only place the token is ever printed. Nothing else logs the response
  // body, and nothing writes it to disk.
  const lines = [
    result.token,
    '',
    'Set this in your shell before running the plugin (add it to your .env only',
    'if your workflow loads that, for example direnv or node --env-file):',
    `H1B_API_TOKEN=${result.token}`,
  ];
  if (result.note) lines.push('', result.note);
  process.stdout.write(`${lines.join('\n')}\n`);
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length !== 1 || args[0] !== 'request') {
    process.stderr.write(`${USAGE}\n`);
    process.exitCode = 2;
    return;
  }

  const result = await mintToken();
  if (!result.ok) {
    // Errors go to stderr and set an exit code rather than calling
    // process.exit, so the stream is flushed before the process ends.
    process.stderr.write(`${result.message}\n`);
    process.exitCode = result.exitCode;
    return;
  }
  render(result);
}

// Run the CLI only when invoked as a script. mintToken is imported by the test
// suite; an unguarded main() would run on import with the importer's argv,
// print usage, and set the IMPORTER's exit code to 2 (test-all.mjs imports
// test files in-process, so that turned the whole suite red).
if (isMainModule(import.meta.url)) {
  main().catch(err => {
    const message = displayClean((err && err.message) ? err.message : err);
    process.stderr.write(`could not issue a key (${message})\n`);
    process.exitCode = 1;
  });
}

// @ts-check
// Notion API helper for the notion plugin. Ported from the notion-lib.mjs
// contributed by @pcomans in #959 (with thanks), reshaped for the plugin layer:
//
//  - No module-level secrets / `import 'dotenv/config'`. The token + parent page
//    id are passed into createNotionClient() from the plugin's scoped ctx.env,
//    so nothing reads process.env at import time and the engine stays the place
//    that decides when .env is loaded.
//  - templates/states.yml (the canonical status source of truth) is resolved
//    from the repo root, two levels up from this bundled plugin.
//
// Pages use Notion's native markdown on both sides. The 360ms inter-request
// sleep keeps us under ~3 req/s. DB resolution is by NAME so no workspace id is
// ever embedded. Files prefixed with _ are never discovered as plugins.

import { readFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import * as yaml from 'js-yaml';

const DIR = dirname(fileURLToPath(import.meta.url));
const STATES_PATH = join(DIR, '..', '..', 'templates', 'states.yml');
const MAX = 1900; // safety margin under Notion's 2000-char rich_text limit

// ── canonical states (templates/states.yml is the source of truth) ──────────
let _states;
function loadStates() {
  if (_states) return _states;
  const doc = yaml.load(readFileSync(STATES_PATH, 'utf-8'));
  const labels = [], aliasMap = {};
  for (const s of doc.states) {
    labels.push(s.label);
    aliasMap[s.label.toLowerCase()] = s.label;
    for (const a of (s.aliases || [])) aliasMap[String(a).toLowerCase()] = s.label;
  }
  _states = { labels, aliasMap };
  return _states;
}
/** Canonical label for a status (case-insensitive, alias-aware), or null. */
export function canonicalStatus(raw) {
  if (!raw) return null;
  const key = String(raw).replace(/\*\*/g, '').trim().toLowerCase();
  return loadStates().aliasMap[key] || null;
}
export function statusLabels() { return loadStates().labels.slice(); }

// ── text → rich_text for property values (chunk-safe under the 2000-char limit) ──
export function rich(text) {
  const str = String(text ?? '');
  const out = [];
  for (let i = 0; i < str.length || out.length === 0; i += MAX) out.push({ type: 'text', text: { content: str.slice(i, i + MAX) } });
  return out;
}

export function plain(prop) {
  return (prop?.title || prop?.rich_text || []).map((t) => t.plain_text).join('');
}

/**
 * Build a Notion client bound to one user's token + parent page. Network goes
 * through the injected `fetchFn` (the plugin passes ctx.fetch so the engine's
 * allowedHosts/HTTPS/redirect guard applies); falls back to global fetch for
 * standalone use. Nothing here reads process.env.
 * @param {{ token: string, parent: string, fetch?: Function }} cfg
 */
export function createNotionClient({ token, parent, fetch: fetchFn = globalThis.fetch }) {
  if (!token) throw new Error('NOTION_ACCESS_TOKEN is not set (.env) — the Notion plugin needs it to read/write.');
  const HEADERS = { Authorization: `Bearer ${token}`, 'Notion-Version': '2025-09-03', 'Content-Type': 'application/json' };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  async function api(path, method, body) {
    await sleep(360); // ~3 req/s
    // ctx.fetch throws on non-2xx (its message carries the body); the !r.ok
    // branch below is the fallback when a plain global fetch is injected.
    const r = await fetchFn(`https://api.notion.com/v1/${path}`, { method, headers: HEADERS, body: body ? JSON.stringify(body) : undefined });
    const j = await r.json();
    if (!r.ok) throw new Error(`Notion ${method} ${path} -> ${j.code}: ${j.message}`);
    return j;
  }

  /** Create a page in a data source. `markdown` (optional) becomes the page body. */
  async function createPage(dataSourceId, properties, markdown) {
    const body = { parent: { type: 'data_source_id', data_source_id: dataSourceId }, properties };
    if (markdown) body.markdown = markdown;
    return api('pages', 'POST', body);
  }

  /** Map of DB name → primary data source id for every DB under the parent page. */
  async function resolveDBs() {
    if (!parent) throw new Error('Set NOTION_PARENT_PAGE_ID in .env (the "Career Ops" parent page id).');
    const out = {};
    let cursor;
    do {
      const j = await api(`blocks/${parent}/children?page_size=100${cursor ? `&start_cursor=${cursor}` : ''}`, 'GET');
      for (const b of j.results) {
        if (b.type !== 'child_database') continue;
        const db = await api(`databases/${b.id}`, 'GET');
        out[b.child_database.title] = db.data_sources?.[0]?.id;
      }
      cursor = j.has_more ? j.next_cursor : null;
    } while (cursor);
    return out;
  }

  async function queryDB(dataSourceId) {
    let cursor, all = [];
    do {
      const j = await api(`data_sources/${dataSourceId}/query`, 'POST', { page_size: 100, start_cursor: cursor });
      all.push(...j.results);
      cursor = j.has_more ? j.next_cursor : null;
    } while (cursor);
    return all;
  }

  function summarize(r) {
    return {
      id: r.id,
      company: plain(r.properties.Company),
      role: plain(r.properties.Role),
      status: r.properties.Status?.select?.name || '',
      score: r.properties.Score?.number ?? null,
      jobUrl: r.properties.URL?.url || '',
      url: r.url,
    };
  }

  /** Match against "<company> / <role>" (substring, case-insensitive) or exact company. */
  async function findRecords(dataSourceId, match) {
    const m = String(match).toLowerCase().trim();
    return (await queryDB(dataSourceId)).map(summarize).filter((r) => {
      const hay = `${r.company} / ${r.role}`.toLowerCase();
      return hay.includes(m) || r.company.toLowerCase() === m;
    });
  }

  return { api, createPage, resolveDBs, queryDB, findRecords };
}

// @ts-check
// ── Reference seed ── This bundled plugin is a stable, reviewed example. To
// extend it, publish career-ops-plugin-<id> with "supersedesBundled": true and
// your version takes precedence once installed (see docs/PLUGINS.md). Bundled
// seeds take only security/compat fixes — feature work happens in the successor repo.
//
// Notion plugin — mirror your tracker to a Notion database (export) and read
// records back as job leads (search).
//
// Built on the Notion backend contributed by @pcomans in #959 (with thanks),
// reshaped per the plugin contract. The decisive change: Notion is an OPT-IN
// MIRROR, not a replacement backend. data/applications.md stays the canonical
// source of truth (the web reads it); `export` pushes a read-only snapshot of it
// to the user's own Notion DB. The core never writes to Notion as primary, and
// modes are not edited — this lives entirely behind `node plugins.mjs run notion`.
//
// Setup: a "Career Ops" parent page in Notion containing an "Applications" DB
// with Company / Role / Status / Score / URL properties, shared with your
// internal integration. Enable in config/plugins.yml; keys in .env.
//
//   node plugins.mjs run notion export            # mirror tracker → Notion
//   node plugins.mjs run notion search "platform" # read matching records → pipeline

import { createNotionClient, rich, canonicalStatus } from './_notion.mjs';

function clientFromCtx(ctx) {
  return createNotionClient({
    token: ctx?.env?.NOTION_ACCESS_TOKEN,
    parent: ctx?.env?.NOTION_PARENT_PAGE_ID,
    fetch: ctx?.fetch, // route through the engine's allowedHosts/redirect guard
  });
}

async function applicationsDb(client) {
  const dbs = await client.resolveDBs();
  const apps = dbs['Applications'];
  if (!apps) throw new Error('No "Applications" database found under the Career Ops page — create it and share the integration with it.');
  return apps;
}

/**
 * Parse a tracker score cell into a numeric value for the Notion DB Score property.
 *
 * Scores in applications.md may be formatted like `4.2/5`, `**4.2/5**`, `4.25`, etc.
 * Strips formatting and extracts the first numeric value so slash-formatted
 * scores (e.g. 4.2/5) are not mangled into 4.25 (#1414).
 *
 * @param {unknown} s - Raw score value from tracker row.
 * @returns {number} Parsed score, or NaN if no valid number is present.
 */
export function parseScore(s) {
  const m = String(s ?? '').replace(/\*\*/g, '').match(/([\d.]+)/);
  return m ? parseFloat(m[1]) : NaN;
}

export default {
  parseScore,

  /**
   * export: upsert each tracker row into the user's Notion Applications DB.
   * Receives a frozen read-only snapshot of the tracker — never a file handle.
   * @param {{ applications: Array<Record<string,string>> }} snapshot
   * @param {any} ctx
   */
  async export(snapshot, ctx) {
    const rows = Array.isArray(snapshot?.applications) ? snapshot.applications : [];
    if (rows.length === 0) return { pushed: 0 };
    const client = clientFromCtx(ctx);
    const apps = await applicationsDb(client);

    let pushed = 0;
    for (const row of rows) {
      const company = (row.company || '').trim();
      const role = (row.role || '').trim();
      if (!company || !role) continue;

      const props = { Role: { title: rich(role) }, Company: { rich_text: rich(company) } };
      const status = canonicalStatus(row.status);
      if (status) props.Status = { select: { name: status } };
      const score = parseScore(row.score);
      if (Number.isFinite(score)) props.Score = { number: score };

      if (ctx?.dryRun) { ctx.log(`would push: ${company} — ${role}`); pushed++; continue; }

      // Upsert: update an existing company+role record, else create one.
      const dupes = (await client.findRecords(apps, `${company} / ${role}`))
        .filter((h) => h.company.toLowerCase() === company.toLowerCase() && h.role.toLowerCase() === role.toLowerCase());
      if (dupes.length) await client.api(`pages/${dupes[0].id}`, 'PATCH', { properties: props });
      else await client.createPage(apps, props);
      pushed++;
    }
    return { pushed };
  },

  /**
   * search: return Notion records matching a query as Job[]. Only records that
   * carry a job posting in a `URL` property are returned (e.g. a postings DB, or
   * leads you added in Notion). Note: `export` mirrors the tracker (company/role/
   * status/score) and does NOT set a job URL, so export-created rows are not
   * round-tripped by search — that's intentional, they already live in your
   * tracker. The engine writes any results to the pipeline canonically.
   * @param {string} query
   * @param {any} ctx
   */
  async search(query, ctx) {
    const client = clientFromCtx(ctx);
    const apps = await applicationsDb(client);
    const hits = await client.findRecords(apps, query);
    return hits
      .filter((h) => h.jobUrl && /^https?:\/\//i.test(h.jobUrl))
      .map((h) => ({ title: h.role || 'Notion record', url: h.jobUrl, company: h.company || '', location: '' }));
  },
};
